import json,csv
from pathlib import Path
P=Path(__file__).resolve().parent
talks=[];items=[];problems=[];corrections=[]
def talk(record,date,speaker,pages,title,kind,summary):
 talks.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind=kind,summary=summary));save()
def item(record,pages,kind,title,notes,statement,reconstruction,cls,fate,refs=(),**kw):
 n=1+sum(x['record']==record for x in items)
 d=dict(id=f'1975-{record}.{n}',record=record,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cls},fate=fate,present_status=r'As of 10 November 2026, the result is established in the stated scope.',literal_correctness='correct with missing hypotheses',publication_match='exact',verification='read the result',development='annotated',problem='',worth='',refs=list(refs),confidence='high',area='Integrable systems')
 d.update(kw);items.append(d);save();return d['id']
def correction(page,place,reads,correct,evidence,applies='both',typ='faithful_error'):
 corrections.append(dict(page=page,place=place,transcription_reads=reads,should_read=correct,evidence=evidence,applies_to=applies,type=typ));save()
def problem(id,title,statement,occurrences,status,refs):
 problems.append(dict(id=id,title=title,statement=statement,occurrences=occurrences,status=status,status_date='2026-11',refs=refs));save()
def save():
 def clean(x):
  if isinstance(x,str):return x.replace("\\'","'").replace(r'g_i\prime',r'g_i^{\prime}').replace(r'\lambda_B\prime',r'\lambda_B^{\prime}').replace(r'\Lambda\prime',r'\Lambda^{\prime}')
  if isinstance(x,list):return [clean(z) for z in x]
  if isinstance(x,dict):return {k:clean(v) for k,v in x.items()}
  return x
 for name,data in [('talks',talks),('items',items),('problems',problems)]:
  (P/f'b_{name}.json').write_text(json.dumps(clean(data),ensure_ascii=False,indent=2)+'\n')
 with (P/'b_corrections.csv').open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writeheader();w.writerows(clean(corrections))

DMN='dubrovinmatveevnovikov1976nonlinear';DUB='dubrovin1977matrix';DRI='drinfeld1977commutative';KRI='krichever1976zakharov'
talk(375,'1975-10-27','B. A. Dubrovin','P000623-P000628','Matrix finite-gap operators and Jacobians','talk',r'The dated heading on P000625 begins Dubrovin\'s talk; P000623--P000624 continue Krichever\'s preceding talk. Dubrovin constructs matrix hierarchies, reduces their stationary equations to a polynomial matrix Lax equation, and identifies generic isospectral sets with a diagonal-group bundle over a Jacobian. The actual mathematical span is P000625--P000626. A sign reversal in the commutator equation is a notebook error, not a change of convention that can consistently be retained.')
item(375,'P000625','construction','Regular diagonal spectral pencil and diagonal gauge',r'The pencil is \(D+U-EA\), with \(A=\operatorname{diag}(a_1,\ldots,a_n)\), distinct \(a_i\), and \(U_i^i=0\), which the notes say can always be achieved.',r'On an interval, for a smooth complex matrix \(U\) and constant diagonal \(A\) with pairwise distinct entries, a diagonal invertible gauge \(g\) satisfying \(g_i\prime=-U_{ii}g_i\) transforms \(g^{-1}(D+U-EA)g\) to a pencil with zero diagonal potential. A periodic gauge exists only when the diagonal holonomies permit it; the local assertion does not automatically preserve the periodic boundary condition.',r'The gauge equation and its global obstruction are explicit reconstructions; neither qualification is written.', 'A',r'The regular-diagonal matrix setup appears in \citet[Ch.~III, \S2]{dubrovinmatveevnovikov1976nonlinear}; the paper was received 2 June 1975 and published in 1976. Receipt is not evidence of public circulation before this talk.',[DMN])
item(375,'P000625','construction','Formal diagonal resolvents and commuting matrix flows',r'For diagonal constant \(B\), the notes seek \(\lambda_B=B+\sum_{j\ge1}\lambda_{j,B}E^{-j}\) satisfying \(\lambda_B\prime=[\lambda_B,U-EA]\), and set \(U_t=[A,\lambda_{N+1,B}]\).',r'Fix the formal diagonalization normalized to the identity at \(E=\infty\), and fix its diagonal integration constants. The equation determines the off-diagonal coefficients recursively because \(\operatorname{ad}A\) is invertible there. With the usual normalized diagonal resolvent, the resulting coefficients are differential polynomials in \(U\), and truncations give the matrix hierarchy. The displayed differential equation alone, without normalization, does not select a unique resolvent.',r'Normalization and the distinction between off-diagonal recursion and diagonal constants have been supplied; the notebook asserts polynomial dependence without giving that construction.', 'A',r'Compare the normalized construction in \citet[Ch.~III, \S2]{dubrovinmatveevnovikov1976nonlinear} and its matrix elaboration in \citet[\S1]{dubrovin1977matrix}.',[DMN,DUB])
item(375,'P000625','theorem','Isospectral Lax evolution',r'All displayed flows are said to preserve the spectrum, since \(L_t=[L,M_N]\).',r'For the spectral pencil, the auxiliary operator must give the compatible pair \([\partial_t-M_N,\partial_x+U-EA]=0\), with signs chosen consistently. For a periodic smooth potential and periodic auxiliary coefficients, the monodromy evolves by conjugation, so its characteristic polynomial and Floquet multipliers are constant. On a noncompact domain, preservation of an operator spectrum additionally requires a specified realization and suitable decay or boundedness conditions.',r'The notebook leaves the spectral meaning and domain unspecified; the periodic monodromy formulation makes one exact assertion that its calculation supports.', 'A',r'This hierarchy is treated in \citet[Ch.~III, \S2]{dubrovinmatveevnovikov1976nonlinear}.',[DMN])
item(375,'P000625-P000626','construction','Stationary equations and the polynomial matrix Lax equation',r'The stationary condition is \([L,M_N]=0\). The talk first writes \(\Lambda\prime=[\Lambda,Q]\), but its lemma and proof reverse the commutator to \([Q,\Lambda]\), with \(Q=U-EA\).',r'Restrict the commuting auxiliary differential operator to the local solution space of \((D+Q)\psi=0\); elimination of derivatives yields a polynomial matrix \(\Lambda(E,x)\). The condition \([D+Q,\Lambda]=0\) is exactly \(\Lambda\prime=[\Lambda,Q]\). Hence \(\det(zI-\Lambda(E,x))\) is independent of \(x\).',r'The first sign in the notebook is retained and the two later signs are emended by direct expansion of the commutator.', 'A',r'The stationary matrix reduction is part of \citet[Ch.~III, \S2]{dubrovinmatveevnovikov1976nonlinear}. The sign correction is checked algebraically from the notebook\'s own definition of \(Q\).',[DMN],literal_correctness='false as written')
item(375,'P000626','definition','Algebraic finite-gap eigenfunction and spectral curve',r'A polynomial pencil is called finite-gap when an eigenfunction is meromorphic on a fixed finite-genus covering of the \(E\)-plane, with essential singularities allowed over infinity. The proposed curve is \(R(z,E)=\det(zI-\Lambda(E))=0\).',r'Take the normalization and compactification of the reduced irreducible spectral curve, with marked points above \(E=\infty\). On a regular component with generically simple eigenvalue, a common solution \((D+Q)\psi=0\), \(\Lambda\psi=z\psi\) defines the algebraic eigenline data; its normalized eigenfunction is meromorphic away from those points with prescribed exponential behavior there. This algebraic use of finite-gap is not itself a statement that a general matrix operator has a self-adjoint spectrum with finitely many real gaps.',r'Reduction, normalization, generic simplicity and the distinction from a real spectral-gap assertion are reconstructed hypotheses.', 'A',r'For the matrix spectral-curve construction see \citet[Ch.~III, \S2]{dubrovinmatveevnovikov1976nonlinear}.',[DMN])
item(375,'P000626','claim','Bloch property of the common eigenfunction',r'If \(U(x+T)=U(x)\), the simultaneous eigenfunction is said to be a Bloch function because translation commutes with \(\Lambda\).',r'If both \(Q\) and the polynomial matrix \(\Lambda\) are \(T\)-periodic, their monodromy commutes with \(\Lambda(E,0)\). On each one-dimensional eigenspace at a simple point of the spectral curve, monodromy therefore acts by a scalar: \(\psi(x+T,P)=\mu(P)\psi(x,P)\). At a repeated eigenvalue one must choose a common eigenvector or allow generalized spectral data; an arbitrary vector in the repeated eigenspace need not be Bloch.',r'The simple-eigenline qualification and exceptional-point distinction make explicit the linear algebra behind the notebook remark.', 'A',r'The Bloch/spectral-curve interpretation belongs to \citet[Ch.~III, \S2]{dubrovinmatveevnovikov1976nonlinear}.',[DMN])
item(375,'P000625-P000626','theorem','Complete integrability of stationary matrix systems',r'The stationary equations are called completely integrable Hamiltonian systems. Coefficients \(I_{ij}\) of \(R(z,E)\) are asserted to be commuting integrals.',r'For the stationary matrix hierarchy with its specified Hamiltonian structure, restrict to a regular symplectic leaf, fix the Casimirs, and require a smooth spectral curve and functional independence of the remaining spectral invariants. Complete integrability means that half the leaf dimension is supplied by independent pairwise Poisson-commuting integrals. Constancy of \(R\) follows from the Lax equation alone; involution and completeness require this additional Hamiltonian theorem.',r'The notebook does not display a Poisson bracket, its Casimirs, or the independence locus; these qualifications delimit its claim rather than supply a missing proof.', 'A',r'The matrix integrability theorem is stated in \citet[Ch.~III, \S2, p.~117]{dubrovinmatveevnovikov1976nonlinear}; further details appear in \citet[\S\S1--3]{dubrovin1977matrix}.',[DMN,DUB],publication_match='partial')
iso=item(375,'P000626','problem','Recovering matrix potentials with a fixed spectral curve',r'The explicit problem asks for all finite-gap \(L\) with the same curve \(\Gamma\). The announced answer is a principal \(\pi\)-bundle over its Jacobian, where \(\pi\) is the diagonal invertible group modulo scalar matrices.',r'Fix the regular diagonal leading matrix, the polynomial spectral invariants, marked points and local spectral normalization. For a smooth generic spectral curve, the nonsingular rank-one spectral data parametrize an open part of its Jacobian; eigenvector normalization retains a diagonal gauge torsor \(\pi\cong(\mathbb C^*)^{n-1}\). The reconstruction generally produces meromorphic potentials. The assertion must be restricted to the regular spectral-data locus and does not identify every singular or globally smooth real isospectral set with an entire compact Jacobian.',r'The open-locus and meromorphic qualifications, and the distinction between quotient and framed data, are explicit modern reconstructions.', 'A',r'The answer is in \citet[Ch.~III, \S2, p.~117]{dubrovinmatveevnovikov1976nonlinear} and \citet[theorem on p.~269]{dubrovin1977matrix}. The latter was received 7 December 1976 and printed in volume 11 (1977); these dates must not be replaced by its later translation copyright.',[DMN,DUB],problem='GP-1975-11')
problem('GP-1975-11','Matrix finite-gap inverse problem at fixed spectral curve',r'Classify the regular rank-one matrix pencils \(D+U-EA\), with fixed distinct diagonal entries of \(A\), whose stationary spectral polynomial is a fixed smooth curve, and distinguish framed potentials from their diagonal-gauge quotient.',[iso],r'As of November 2026, solved on the regular algebraic-geometric locus by the Jacobian construction announced here and published in 1976--1977. Related scalar precursors are 1974-336.15 and 1974-340.8; their differently quantified problems are not merged.',[DMN,DUB])
correction('P000625-P000626','stationary Lax lemma and proof',r'\(\Lambda\prime=[Q,\Lambda]\)',r'\(\Lambda\prime=[\Lambda,Q]\)',r'The scans show the reversed sign at the bottom of P000625 and in P000626; the earlier equation on P000625 has the consistent order. Since \([D+Q,\Lambda]=\Lambda\prime+[Q,\Lambda]\), the later signs are faithful notebook errors.')

talk(376,'1975-11-10','I. M. Gelfand','P000626-P000629','Geometry and mathematical preparation for physicists','talk',r'The heading and informal lecture occur on P000627, continuing at the top of P000628 before Polyakov begins. An ant on a cube motivates curvature and torsion, followed by a programme for geometry and relativity on lattices, a physics reading list, and mathematics proposed for physicists. Bare subject names are recorded as a curriculum remark rather than converted into nonexistent conjectures.')
item(376,'P000627','remark','Development of loops, curvature and torsion',r'An ant moving on a cube and a curve developed from a plane are used to distinguish a displacement from a rotation, labelled torsion and curvature.',r'For an affine connection with solder form \(\theta\) and connection form \(\omega\), torsion is \(T=d\theta+\omega\wedge\theta\), while curvature is \(\Omega=d\omega+\omega\wedge\omega\). Infinitesimal affine development relates their translational and rotational effects. An arbitrary finite loop\'s developed displacement is not by itself a torsion tensor; the intrinsic Levi-Civita geometry of a Euclidean polyhedral surface is torsion-free, with curvature concentrated in angle deficits at vertices.',r'The differential-form formulation and the warning about finite-loop development are explanatory reconstruction. The sketch does not specify a connection with nonzero torsion.', 'E',r'This is an informal exposition of connection geometry. \citet[abstract and polyhedral construction]{regge1961relativity} gives the relevant pre-talk polyhedral curvature setting, but does not verify every assertion of the ant analogy.','regge1961relativity'.split(),area='Differential geometry',publication_match='thematic only',verification='publisher metadata checked',literal_correctness='not determinable')
item(376,'P000627','question','Characteristic classes and basic geometry on polyhedra',r'Gelfand asks how to build basic geometry, including characteristic classes, on higher-dimensional polyhedra.',r'The notes specify no category of polyhedra, tangential structure, or desired definition. For a triangulated closed smooth \(n\)-manifold there is a precise existing instance: the mod-two sum of all \(p\)-simplices of its first barycentric subdivision represents the Poincare dual of \(w_{n-p}(TM)\). This example is evidence about the programme, not an identification of a new theorem being proposed.',r'The restricted manifold example is supplied to locate the discussion; no assertion is made for arbitrary singular polyhedra.', 'E',r'The relevant pre-talk instance is \citet[Theorem 1 and its mod-two corollary, pp.~511--512]{halperintoledo1972stiefel}; the same construction is discussed explicitly in Fuchs\'s intervention on P000635.', ['halperintoledo1972stiefel'],area='Topology',publication_match='partial')
item(376,'P000627','problem','General relativity on a lattice',r'The notebook explicitly says: \ru{Задача: сделать общую относительность на решетках}.',r'One can assign edge lengths to a simplicial complex, use flat metrics on its top-dimensional simplices, and concentrate curvature on codimension-two hinges. In four dimensions the Regge action is proportional to the sum of hinge areas times deficit angles. A mathematically definite new problem would have to specify a discretization, approximation class, limit, and convergence criterion; none is given here.',r'The simplicial realization is a historical comparison, not evidence that Gelfand specified that model or a convergence theorem.', 'E',r'\citet[abstract]{regge1961relativity} had already proposed a polyhedral formulation of general relativity in 1961. The opened publisher record confirms that prior programme; this broad seminar request is not assigned a new open-problem identifier.',['regge1961relativity'],area='Mathematical physics',publication_match='partial',verification='publisher metadata checked',literal_correctness='not determinable',present_status=r'As of 10 November 2026, the historical request has established realizations; the notes do not specify a particular remaining convergence problem.')
item(376,'P000627-P000628','remark','Reciprocal mathematics and physics curricula',r'The physics list names Feynman--Hibbs, Feynman\'s lectures and statistical mechanics, Landau--Lifshitz, Berestetskii--Lifshitz--Pitaevskii, and Dirac. The mathematics list includes representations, pseudodifferential and Fourier integral operators, Riemann--Roch, singularities and topological cycles.',r'This is a pedagogical proposal to teach established mathematical and physical subjects across the two communities. It states no common theorem, prerequisite graph, or new research question. The separate functional equation for a polynomial is indexed in the next item.',r'No individual textbook edition is reconstructed from abbreviated names, and bare topic names are not inflated into conjectures.', 'E',r'The notebook is the direct evidence for the curriculum. Its sole displayed mathematical theorem is independently matched below to \citet{bernstein1972continuation}.',['bernstein1972continuation'],area='Exposition',publication_match='thematic only',verification='publisher metadata checked',literal_correctness='correct',present_status=r'As of 10 November 2026, this remains a historical teaching programme, with no theorem-level status to resolve.')
item(376,'P000628','theorem','The polynomial functional equation',r'The example under singularities is \(L P^\lambda=a(\lambda)P^{\lambda-1}\).',r'For a nonzero polynomial \(P\in\mathbb C[x_1,\ldots,x_n]\), there are a nonzero polynomial \(b(s)\in\mathbb C[s]\) and a differential operator \(Q(s)\) with coefficients in \(\mathbb C[x,s]\) satisfying \(Q(s)P^{s+1}=b(s)P^s\) in the formal localization module. Taking \(s=\lambda-1\) gives the notebook\'s convention. Allowing polynomial dependence of the operator on the exponent is essential.',r'The coefficient ring, formal meaning of the powers and shift of the exponent are supplied.', 'E',r'\citet[functional equation theorem]{bernstein1972continuation} published this in 1972, before the talk. The opened publisher record verifies the article; the formula here is also the explicit subject of the supplied notes.',['bernstein1972continuation'],area='D-modules',verification='publisher metadata checked')
WIL='wilson1974confinement';JAW='jaffewitten2000yangmills';LEV='levinfrankfurt1968quark'
talk(377,'1975-11-10','A. M. Polyakov','P000627-P000632','Quark representations, color and the Wilson-loop confinement problem','talk',r'Polyakov begins on P000628 after Gelfand\'s reading programme and finishes on P000630. The discussion moves from hadron representations and quark statistics to color gauge invariance, infinitely heavy probes, rectangular Wilson loops and a Gaussian Abelian comparison. Representation identities, phenomenological approximations, established constructions and the unsolved four-dimensional confinement question are separated. A reference to the penultimate issue of \emph{Theoretical and Mathematical Physics} lacks an author, title or year sufficiently specific to identify a paper.')
item(377,'P000628','claim','Quark content, spin and resonance shorthand',r'The notes introduce three spin-\(1/2\) quarks \(u,d,s\), label baryons spin \(1/2\) and mesons spin zero, and describe resonances as orbital excitations.',r'In the simplest constituent model, conventional baryons have valence content \(qqq\), while conventional mesons have \(q\bar q\). Their spins are obtained by coupling constituent spins and orbital angular momentum; baryons need not have spin \(1/2\), and mesons need not have spin zero. An orbital-excitation model describes some resonances but is not a definition of every hadronic resonance.',r'The spin labels are restricted to examples; their literal universal reading is false even for the spin-\(3/2\) baryon discussed later on the same page.', 'E',r'The pre-talk review \citet[\S I and Appendix I]{levinfrankfurt1968quark} already includes spin-\(3/2\) baryons and spin-one mesons. These are old model distinctions, not a later correction discovered by this seminar.',[LEV],area='Particle physics',literal_correctness='false as written',publication_match='partial')
item(377,'P000628','theorem','Flavor tensor products for mesons and baryons',r'The page lists \(\bar3\otimes3=1\oplus8\), \(3^{\otimes3}=1\oplus8\oplus8\oplus10\), and \(3\otimes3=\bar3\oplus6\).',r'For the complex defining representation \(V\) of \(SU(3)\), \(V^*\otimes V=\mathbb C\oplus\mathfrak{sl}_3\), \(\Lambda^2V\cong V^*\), and \(V^{\otimes3}\cong\mathbb C\oplus\mathfrak{sl}_3^{\oplus2}\oplus\operatorname{Sym}^3V\). The displayed dimensions are \(9=1+8\), \(9=3+6\), and \(27=1+8+8+10\). These are exact representation identities; assigning them to flavor multiplets is a physical model.',r'The vector-space notation distinguishes an exact tensor decomposition from empirical approximate flavor symmetry.', 'E',r'The quark-model context predates the talk: \citet[pp.~214--215; publisher metadata]{gellmann1964schematic}. The identities themselves follow directly from tensor symmetry and are explicitly present in the notebook.',['gellmann1964schematic'],area='Representation theory',literal_correctness='correct',verification='publisher metadata checked')
item(377,'P000628','claim','The additive-quark total-cross-section ratio',r'For high-energy baryon--baryon and baryon--meson scattering, the ratio is recorded as \(3/2\), to about ten percent; particle and antiparticle cross sections are said to coincide.',r'If a high-energy additive constituent model assigns the same effective scattering strength to each valence quark or antiquark, with negligible multiple-scattering and wavefunction corrections, constituent counting gives \(\sigma(BB)/\sigma(BM)\approx9/6=3/2\). Equality of particle and antiparticle total cross sections concerns an asymptotic scattering statement under additional analyticity and growth assumptions, not an exact equality at all energies. The stated ten-percent agreement is a historical estimate without a specified dataset.',r'The factorization assumptions and separation from an asymptotic theorem are supplied; no present experimental error bound is inferred.', 'E',r'\citet[Introduction, p.~108, and \S VII]{levinfrankfurt1968quark} explicitly discusses this ratio under a Pomeranchuk-limit assumption before 1975.',[LEV],area='Particle physics',publication_match='partial')
item(377,'P000628','remark','The historical absence of pentaquarks',r'The notes say that a \(qqqq\bar q\) configuration has not been observed.',r'As a dated empirical remark this concerns the evidence available to the speaker in November 1975. It is not a representation-theoretic prohibition: \(3^{\otimes4}\otimes\bar3\) contains color singlets. A later observation of resonances consistent with such minimal valence content does not by itself determine a compact five-quark rather than molecular internal structure.',r'The minimal-content and internal-structure distinction is supplied to prevent the historical sentence being read as a theorem.', 'B',r'\citet[abstract]{lhcb2015pentaquark}, first submitted 13 July 2015, reported hidden-charm structures consistent with pentaquark states. This changes the historical observational context; it does not settle their microscopic binding mechanism.',['lhcb2015pentaquark'],area='Particle physics',literal_correctness='correct',publication_match='partial',present_status=r'As of 10 November 2026, the 1975 non-observation statement is historical and cannot be repeated as a present exclusion.')
item(377,'P000628-P000629','construction','Color, fermion statistics and singlet tensors',r'The symmetric \(uuu\) state of \(\Delta^{++}\) motivates three colors and an antisymmetric color factor; the notes also display a colorless meson sum.',r'For three identical spin-\(1/2\) quarks in a symmetric spatial, spin and flavor state, the antisymmetric tensor \(\varepsilon_{abc}\) in color \(\mathbb C^3\) supplies the required fermionic antisymmetry. A color-singlet meson contraction is \(\sum_a\bar q_a q_a\), while a baryon contraction is \(\varepsilon_{abc}q_aq_bq_c\). The middle term of the notebook\'s meson sum has two barred factors and must be emended.',r'The fully antisymmetric color tensor is the modern formulation of the notebook\'s proposal. Historical paraquark and three-triplet models are precursors, not literally identical to modern QCD.', 'E',r'Pre-talk precedents are \citet[publisher record]{greenberg1964paraquark} and \citet[abstract]{hannambu1965triplet}; both dates and the latter\'s double-\(SU(3)\) model were checked.',['greenberg1964paraquark','hannambu1965triplet'],area='Particle physics',verification='publisher metadata checked',publication_match='partial',literal_correctness='false as written')
item(377,'P000628-P000629','claim','Approximate flavor symmetry and exact color gauge invariance',r'The discussion contrasts approximately valid flavor \(SU(3)\) with exact color \(SU(3)\), suggests four flavors, and contains the isolated phrase that the Lagrangian cannot be invariant under flavor times color.',r'For quark fields in the fundamental color representation, a common flavor-independent kinetic term is invariant under global flavor rotations and local color gauge transformations. A nondegenerate quark-mass matrix breaks the global flavor symmetry while preserving color gauge invariance. Four flavors give an approximate global \(SU(4)\) only in a mass-degenerate idealization; adding a flavor does not change the color group. The isolated blanket denial of invariance cannot be reconciled literally with the next page without this distinction.',r'The mass-matrix qualification is reconstructed. The numerical 20--30 percent accuracy and dating of a fourth flavor are not converted into rigorous statements.', 'E',r'Four-quark weak-current models already appear in \citet[abstract]{glashowiliopoulosmaiani1970weak}, published 1 October 1970. This verifies a pre-talk four-flavor precedent, not the notebook\'s approximate chronology or percentage.',['glashowiliopoulosmaiani1970weak'],area='Particle physics',verification='publisher metadata checked',publication_match='partial',literal_correctness='not determinable')
item(377,'P000629','definition','The color Yang-Mills Lagrangian and gluons',r'The notebook writes a Dirac kinetic term with a matrix connection and \(\operatorname{tr}F_{\mu\nu}^2/(4e^2)\), and describes eight massless gluons.',r'With gauge group \(SU(3)\), a connection \(A_\mu\in\mathfrak{su}(3)\), curvature \(F_{\mu\nu}=\partial_\mu A_\nu-\partial_\nu A_\mu+[A_\mu,A_\nu]\), and quarks in the defining representation, the classical gauge-invariant action contains \(\bar q(i\gamma^\mu D_\mu-m)q\) and the Yang--Mills quadratic curvature term, with signs depending on metric and Lie-algebra conventions. The eight gauge components have no gauge-invariant bare Proca mass term. This statement does not assert eight massless physical asymptotic particles.',r'The distinction between bare gauge fields and the physical spectrum is supplied; the notebook\'s normalization of the coupling is retained only up to convention.', 'E',r'The pre-talk gauge-theory setting is explicit in \citet[\S III]{wilson1974confinement}. For the later separation of classical masslessness and a quantum mass gap see \citet[\S1]{jaffewitten2000yangmills}.',[WIL,JAW],area='Gauge theory',publication_match='partial')
item(377,'P000629','remark','Conserved currents and noncommutative electrical engineering',r'One marginal remark relates invariance to conservation laws; Gelfand proposes classical noncommutative electrical engineering.',r'For a differentiable action and a continuous global symmetry, Noether\'s first theorem gives an on-shell conserved current, modulo improvement terms. Local gauge symmetry instead gives differential identities among Euler--Lagrange expressions, and its associated charges require boundary conditions. The electrical-engineering phrase supplies no circuit equations, class of networks, or assertion to test.',r'The global/local distinction is a mathematical clarification. No new noncommutative circuit theory is inferred from the metaphor.', 'F',r'The gauge context is identifiable from \citet[\S III]{wilson1974confinement}, but no exact proposed result is identifiable from the remark; searches for the quoted phrase and Gelfand/Polyakov circuit terminology did not identify one.',[WIL],area='Gauge theory',publication_match='thematic only',verification='unresolved lead',literal_correctness='not determinable',speaker='I. M. Gelfand (intervention)',present_status=r'As of 10 November 2026, this remains an unformalized programme remark, not a precise unsolved problem.')
item(377,'P000629','theorem','Variational symmetries and conserved currents',r'The line before the confinement proposal relates conserved currents to the presence of symmetry by a two-way arrow.',r'For a finite-order local Lagrangian with sufficiently differentiable fields and coefficients, an infinitesimal variational symmetry depending on constant parameters gives a current whose divergence is a linear combination of the Euler--Lagrange expressions and hence vanishes on solutions. Boundary terms and currents differing by identically conserved improvements must be treated consistently. A symmetry depending on arbitrary functions instead yields differential identities among the Euler--Lagrange expressions. Gauge charges further depend on boundary conditions; the bare arrow is not a universal bijection between every current and every gauge redundancy.',r'The finite-parameter and arbitrary-function cases are separated, with the local variational and boundary hypotheses supplied. This mathematical assertion is distinct from the unformalized electrical-engineering programme in 1975-377.8.', 'E',r'\citet[\S1, Theorems I--II]{noether1918invariant} states the two classical results. The opened text is Tavel\'s 1971 English translation of the 1918 paper; its later arXiv deposit is not its first publication.',['noether1918invariant'],area='Mathematical physics',publication_match='partial')
conf=item(377,'P000629-P000630','conjecture','A linearly rising potential in four-dimensional pure gauge theory',r'The proposed outcome is \(E(R)\sim R\) for non-Abelian fields, contrasted with \(R^{-1}\) in the Abelian case. Colorless composites should have finite mass while an isolated color charge is excluded from the finite-energy spectrum.',r'A definite reconstruction is the zero-temperature infinite-volume four-dimensional pure \(SU(N)\) Yang--Mills theory, \(N\ge2\), with external fundamental charges and a renormalized rectangular Wilson loop: after removal of perimeter/self-energy terms, \(V(R)=-\lim_{T\to\infty}T^{-1}\log\langle W(R,T)\rangle\) should obey \(\lim_{R\to\infty}V(R)/R=\sigma>0\). Dynamical fundamental matter must be excluded for an asymptotic unbroken string. Noncommutativity alone, without dimension, matter content, phase and continuum hypotheses, is insufficient.',r'The formal action explicitly contains \(d^4x\), indicating the dimension four. The notebook does not specify the continuum/regularization or matter-content conditions. The reconstructed four-dimensional pure-gauge assertion is the unresolved part; a bare infinite mass term is not the meaning of confinement.', 'C',r'\citet[\S IV]{wilson1974confinement} gives the pre-talk strong-coupling lattice mechanism. \citet[\S5]{jaffewitten2000yangmills} separates confinement from the existence-and-mass-gap problem; the official current description \citep{clay2026yangmills} still lists the latter as unresolved. Lattice strong coupling does not establish a continuum area law.',[WIL,JAW,'clay2026yangmills'],area='Gauge theory',problem='GP-1975-10',publication_match='partial',worth=r'Worth retaining as a precise research problem, but a bounded chapter cannot supply the missing four-dimensional continuum construction and positive string tension; dimensional and screening qualifications are the useful contribution here.',present_status=r'As of 10 November 2026, the reconstructed four-dimensional continuum area-law statement remains unproved; fixed-lattice and lower-dimensional results do not close it.')
item(377,'P000629','method','Infinitely heavy charges and suppression of pair creation',r'Taking quark mass \(M\to\infty\) is used to discard quark-pair diagrams and retain paths of two external charges.',r'Static source worldlines arise from an infinite external-mass limit after subtracting their rest energies. Removing dynamical quark loops is a separate pure-gauge or quenched assumption, or a decoupling limit for every dynamical quark mass. Infinite mass of the two probes alone does not prevent light dynamical quarks from screening them and breaking the string.',r'The separation of probe and sea-quark masses is a necessary reconstruction that the diagrams do not make explicit.', 'E',r'The loop and screening discussion is already present in \citet[\S II, especially the nearby-vacuum-loop discussion]{wilson1974confinement}.',[WIL],area='Gauge theory',publication_match='partial',problem='GP-1975-10')
item(377,'P000629-P000630','construction','Wilson loops and extraction of a static energy',r'The field integral contains \(\operatorname{tr}\exp(i\oint A)\); its meaning is given by an ordered product. The rectangle has sides \(R,T\). One line says \(W\to ET\), whereas the next page uses \(e^{-iET}\).',r'The gauge-invariant loop is the trace of the path-ordered holonomy. In a Euclidean regulated formulation with a positive transfer operator, a rectangular loop has a spectral expansion \(\sum_n c_n(R)e^{-E_n(R)T}\), and nonzero overlap with the lowest state yields \(-T^{-1}\log\langle W(R,T)\rangle\to V(R)\), after source-energy subtraction. In real time the amplitude is \(e^{-iET}\), so writing it as \(e^{iW}\) gives \(W=-ET\).',r'The Euclidean spectral interpretation, overlap hypothesis and subtraction are supplied. Path ordering is already present in the notebook\'s product definition and is not an omitted operation.', 'E',r'This construction and its physical interpretation precede the talk in \citet[\S\S II--III]{wilson1974confinement}.',[WIL],area='Gauge theory',literal_correctness='false as written',publication_match='partial',problem='GP-1975-10')
item(377,'P000630','method','Worldline phases and the area-law criterion',r'The path-sum explanation uses the phase \(e^{-iET}\), treats an antiparticle as a reversed worldline, and proceeds to \(W(C)\sim\operatorname{area}(C)=RT\), hence \(E(R)\sim R\).',r'For a large rectangular Euclidean loop, an asymptotic law \(\log\langle W(R,T)\rangle=-\sigma RT+\text{perimeter and subleading terms}\) implies the linear static energy after the appropriate successive limits and perimeter subtraction. A worldline representation identifies the observable but does not prove its area law. The latter is an independent dynamical assertion, not a consequence of reversing one trajectory.',r'The conditional implication and order of limits separate the valid extraction method from the unproved dynamical step.', 'E',r'The loop/area-law criterion was formulated in \citet[\S II]{wilson1974confinement}; its unresolved continuum use is item 1975-377.10.',[WIL],area='Gauge theory',publication_match='exact',literal_correctness='correct with missing hypotheses',problem='GP-1975-10',present_status=r'As of 10 November 2026, the conditional criterion is established; proving its premise in four-dimensional continuum pure Yang--Mills theory remains the problem indexed above.')
item(377,'P000630','method','Gaussian Abelian loop and the Coulomb potential',r'The Abelian field integral becomes the exponential of a double line integral of a propagator; the rectangular-loop expression is a term proportional to \(T\) plus a term proportional to \(e^2T/R\).',r'For a centered Gaussian Euclidean gauge field with covariance \(D_{\mu\nu}\) and a conserved regularized loop current \(J\), \(\langle e^{ie(A,J)}\rangle=\exp[-e^2(J,DJ)/2]\). In four-dimensional Maxwell theory, removing the divergent self-energies of two opposite static charges yields \(V(R)=-e^2/(4\pi R)\) in rationalized units. Coincident-point integrals require a regulator; the sign and factor in the notebook depend on propagator and real/Euclidean-time conventions.',r'The regulator, charge signs, units and explicit covariance identity are reconstructed. The \(R^{-1}\) law assumes three spatial dimensions and a massless noncompact Maxwell field.', 'E',r'The Abelian comparison is part of the pre-talk analysis in \citet[\S II]{wilson1974confinement}.',[WIL],area='Gauge theory',publication_match='partial')
item(377,'P000630','remark','Why the non-Abelian integral is not Gaussian',r'The final comparison points to the commutator term in \(F\), and also to multiple extrema for compact Abelian variables.',r'In a non-Abelian gauge theory, \(F=dA+A\wedge A\), so the action contains cubic and quartic interactions in a local gauge potential and is not a Gaussian functional. Compact lattice \(U(1)\) has a nonlinear periodic plaquette action even though its group is Abelian. Thus Gaussian Maxwell calculations cannot decide the infrared phase of either interacting non-Abelian theory or arbitrary compact Abelian models.',r'The distinction between a linear Abelian continuum field and a compact lattice model makes the scope of the comparison explicit.', 'E',r'Both compact Abelian and non-Abelian lattice formulations occur in \citet[\S\S III--IV]{wilson1974confinement}; their strong-coupling behavior is not exclusive to non-Abelian groups.',[WIL],area='Gauge theory',publication_match='partial')
problem('GP-1975-10','Continuum confinement and the static potential',r'For zero-temperature four-dimensional pure \(SU(N)\) Yang--Mills theory with \(N\ge2\), construct a continuum infinite-volume theory and its renormalized external-fundamental-charge observable, and prove a positive asymptotic string tension \(\lim_{R\to\infty}V(R)/R>0\). The notes motivate this statement but leave its matter-content, phase and continuum/regularization qualifications implicit; the formal action already has \(d^4x\).',[conf,'1975-377.11','1975-377.12','1975-377.13'],r'As of November 2026, the four-dimensional continuum statement is unresolved. Wilson\'s 1974 fixed-lattice strong-coupling construction is a prior partial realization, and the existence/mass-gap problem is logically distinct. Record 386 supplies a related Hamiltonian observable, to be linked at integration.',[WIL,JAW,'clay2026yangmills'])
correction('P000628','spin labels','baryons have spin 1/2; mesons spin 0','restrict to the stated low-spin multiplets','The scan faithfully has the shorthand labels; the same page invokes the Delta++ state. Spin-3/2 baryons and spin-1 mesons already occur in Levin and Frankfurt (1968).')
correction('P000628-P000629','flavor times color invariance','L cannot be invariant under SU(3) flavor times SU(3) color','distinguish approximate global flavor symmetry from exact local color gauge invariance','The negative phrase is visible in P000628; P000629 explicitly says color symmetry is exact. The source does not warrant silently deleting the negation.',typ='ambiguity')
correction('P000629','middle term of meson singlet',r'\(\bar q_g\bar q_g\)',r'\(\bar q_g q_g\)','The scan shows two bars. A singlet in the conjugate times defining color representation has one barred and one unbarred factor.')
correction('P000629-P000630','phase of the rectangular Wilson loop',r'\(e^{iW(C)},\quad W(C)\to E(R)T\)',r'\(W(C)\to-E(R)T\) in the real-time convention used on P000630','Both formulas are faithful to the scans. P000630 explicitly writes exp(-iET); a Euclidean convention instead uses exp(-VT).')
talk(378,'','-','P000630-P000632','Year heading: 1976','heading',r'This catalogue record marks the change of calendar year. Its overlapping page links include the end of the November 1975 discussion and the dated 9 February 1976 talk, but provide no independent mathematical assertion. It receives zero occurrence items; all following item identifiers retain academic-year prefix 1975.')
MUL='mulase1990geometric'
talk(379,'1976-02-09','I. M. Krichever','P000630-P000634','Baker-Akhiezer construction of Zakharov-Shabat equations','talk',r'The dated talk occupies P000631--P000632 and the first two lines of P000633. It passes from formal exponential solutions to algebraic spectral data and the uniqueness argument constructing differential operators. Gelfand asks an elementary commuting-operator problem and raises the distinction between a formal series and an analytic function. Drinfeld begins a separate algebraization immediately below on P000633.')
item(379,'P000631','definition','Zero-curvature compatibility for two auxiliary equations',r'The equation is \([L_1-\partial_y,L_2-\partial_t]=0\), with scalar differential operators in \(x\), monic leading terms, and constant next coefficients. Gelfand emphasizes the symmetry of the auxiliary variables.',r'For sufficiently differentiable operator coefficients, compatibility of \(\psi_y=L_1\psi\), \(\psi_t=L_2\psi\) is \(\partial_yL_2-\partial_tL_1=[L_1,L_2]\). The same operator identity makes sense for matrices or operators in other variables, but existence of a common solution requires suitable analytic or formal initial-value conditions. The displayed equation alone is the zero-curvature identity; it does not by itself construct a nonlinear solution.',r'The equivalent sign convention is obtained by expanding the commutator. The original scalar differential setting is distinguished from Gelfand\'s broader operator analogy.', 'A',r'\citet[Theorem 1 and Corollary 1, pp.~291--292]{krichever1976zakharov} constructs solutions in this form. The manuscript was received 8 October 1975 and presented to the Academy on 24 October; neither date alone proves public availability before the February talk.',[KRI],literal_correctness='correct')
item(379,'P000631-P000632','construction','Formal wave-function recursion and its normalization',r'The ansatz is \(\psi=e^{kx+k^ny}\sum_{j\ge0}\xi_jk^{-j}\), \(\xi_0=1\). The written normalization is \(\xi_j(0,y,t)=0\) for \(j>1\).',r'For \(L=D^n+\sum_{i=0}^{n-2}u_iD^i\), formal coefficient comparison in \((L-\partial_y)\psi=0\) recursively determines \(\partial_x\xi_j\). Prescribing \(\xi_j(0,y,t)\) for every \(j\ge1\) fixes the integration functions. A nonzero constant \(D^{n-1}\) coefficient requires the corresponding \(k^{n-1}y\) term in the exponential phase; it is incompatible with the unmodified displayed phase.',r'The normalization bound is emended to \(j\ge1\), and either the next coefficient must vanish or the phase must change. This is a formal calculation and asserts no convergence.', 'A',r'The more general polynomial phase in \citet[conditions 1--2 preceding Theorem 1]{krichever1976zakharov} makes the missing phase term explicit.',[KRI],literal_correctness='false as written',publication_match='partial')
item(379,'P000631-P000633','method','Recovering an operator from a normalized formal wave',r'Conversely, every normalized series is said to determine an operator up to a residual of order \(k^{-1}\); the final proof applies uniqueness to that residual.',r'For a normalized formal wave \(e^{kx+k^ny}(1+\sum_{j\ge1}\xi_jk^{-j})\), comparison of nonnegative powers of \(k\) uniquely gives a monic \(L_n\), with no \(D^{n-1}\) term, for which \(e^{-kx-k^ny}(L_n-\partial_y)\psi=O(k^{-1})\). If the wave also satisfies the nonspecial Baker--Akhiezer conditions below, the residual has the same allowed finite poles and zero leading normalization; uniqueness makes it identically zero. For an arbitrary formal wave only the residual statement follows.',r'The two distinct stages, formal cancellation and global uniqueness, are separated to avoid silently assuming the analytic conclusion.', 'A',r'This is the proof mechanism of \citet[Theorem 1, pp.~291--292]{krichever1976zakharov}.',[KRI])
item(379,'P000631','problem','Commuting scalar operators of orders two and three',r'Gelfand\'s school problem asks when \(L_1=-D^2+u\) and \(L_2=D^3+v_1D+v_2\) commute, with an answer in elliptic functions or elliptic curves.',r'On an interval with smooth complex coefficients, direct comparison of powers of \(D\) gives \(v_1=-3u/2+c_1\), \(v_2=-3u^{\prime}/4+c_2\), and \(u^{(3)}-6uu^{\prime}+4c_1u^{\prime}=0\). Integrating twice gives \((u^{\prime})^2=2u^3-4c_1u^2+2c_3u+c_4\). The solutions are elliptic functions on a nonsingular cubic, or their rational/trigonometric/hyperbolic degenerations, restricted away from poles.',r'The coefficient computation and integration constants are an explicit reconstruction of the exercise, not a new result. Degenerate cubics must be included.', 'E',r'\citet[\S3, equations (2)--(3)]{mulase1990geometric} gives this classical calculation in an equivalent normalization and traces the order-two/order-three case to Wallenberg (1903). The historical attribution is secondary within that research article; the displayed calculation was read and independently expanded here.',[MUL],speaker='I. M. Gelfand (intervention)',problem='GP-1974-10',publication_match='partial')
item(379,'P000631-P000632','definition','Algebraic operator versus merely formal asymptotics',r'An operator is called algebraic when its formal wave extends meromorphically to a compact curve away from one marked point, with poles independent of \(x,y,t\). Gelfand stresses that an asymptotic expansion usually diverges.',r'The intended data are a smooth projective curve \(X\), a marked point \(P\), a local coordinate \(z=k^{-1}\), and a fixed pole divisor away from \(P\). The normalized wave must actually define a holomorphic function near the puncture after removal of its exponential singularity, and a meromorphic function elsewhere. A formal Laurent series does not determine such a global meromorphic function without convergence and continuation conditions.',r'Convergence of the exponential-normalized series and fixed divisor are imposed as parts of this definition, not derived from the coefficient recursion.', 'A',r'The analytic data appear explicitly before \citet[Theorem 1]{krichever1976zakharov}.',[KRI])
item(379,'P000632','question','An unspecified quasianalyticity analogue',r'After contrasting smooth Taylor asymptotics and analytic convergence, Gelfand asks \ru{Аналог квазианалитичности?}',r'No function class, growth sequence, asymptotic sector, or proposed uniqueness implication is specified. The strongest recoverable content is a request to understand when the formal wave data determine an analytic or algebraic object; there is no unique theorem or quantified conjecture to reconstruct.',r'No Denjoy--Carleman condition, Borel summability theorem or differential-Galois criterion is substituted for this sentence.', 'F',r'The analytic construction in \citet{ krichever1976zakharov} assumes specified spectral data and does not answer the unformulated converse. Searches for the quoted terminology with Krichever and Gelfand produced no exact identifiable statement.',[KRI],speaker='I. M. Gelfand (intervention)',verification='unresolved lead',publication_match='thematic only',literal_correctness='not determinable',present_status=r'As of 10 November 2026, the remark remains too underspecified to assign an open-problem status.')
item(379,'P000632','theorem','Existence and uniqueness of the Baker-Akhiezer wave',r'The theorem attributed in the notes to Akhiezer allows a fixed set of poles and says that \(\psi e^{-kx-k^ny}=1+o(k^{-1})\), with uniqueness up to proportionality.',r'Let \(X\) be a smooth compact complex curve of genus \(g\), \(P\in X\), and \(D\) an effective nonspecial divisor of degree \(g\) disjoint from \(P\). Fix a local coordinate \(k^{-1}\) and polynomial exponential phase. For times in the open set on which the normalized interpolation problem is nonsingular, there is a unique wave meromorphic on \(X\setminus\{P\}\), with poles bounded by \(D\), whose exponential-normalized germ is \(1+O(k^{-1})\). With leading coefficient fixed to one, there is no remaining scalar ambiguity.',r'Nonspeciality, degree, open time domain and the large-O correction are supplied. The source\'s Akhiezer attribution is retained historically; its stated multiparameter version is matched to Krichever\'s publication.', 'A',r'\citet[conditions 1--2 and Theorem 1]{krichever1976zakharov} gives the matching construction with a general-position divisor and a \(1+\sum\xi_jk^{-j}\) expansion.',[KRI],literal_correctness='false as written')
item(379,'P000632','example','The elliptic example requires a meromorphic correction factor',r'The elliptic illustration writes an exponential involving the Weierstrass zeta function.',r'The Weierstrass zeta function is quasi-periodic, so \(e^{x\zeta(z)}\) alone is generally not a single-valued function on the elliptic curve. A Baker--Akhiezer function needs a sigma- or theta-function ratio whose quasi-period multiplier cancels that of the exponential, together with the prescribed fixed pole and normalization. This is the genus-one instance of the preceding construction.',r'The displayed exponential is treated as the essential-singularity factor, not a complete global formula.', 'A',r'The finite-pole and global-meromorphic requirements in \citet[conditions 1--2]{krichever1976zakharov} identify exactly what the isolated exponential omits.',[KRI],literal_correctness='false as written',publication_match='partial')
correction('P000631','normalization of formal wave coefficients',r'\(\xi_i(0,y,t)=0\) for \(i>1\)',r'\(\xi_i(0,y,t)=0\) for \(i\ge1\), if this is to fix every integration function','The Russian transcription and scan explicitly show i>1. The recurrence leaves the integration function in xi_1 undetermined under that bound.')
correction('P000631','phase and constant next coefficient',r'\(u_{n-1}=\mathrm{const}\), \(e^{kx+k^ny}\)',r'require \(u_{n-1}=0\), or add \(u_{n-1}k^{n-1}y\) to the phase','The coefficient of k^{n-1} in the substituted equation is u_{n-1}; the scan records no corresponding term in the phase.')
correction('P000632','normalized Baker-Akhiezer asymptotic',r'\(1+o(1/k)\)',r'\(1+O(1/k)\)','The scan and Russian text have a small o, but the preceding series explicitly permits a nonzero xi_1/k term.')
correction('P000632','Baker-Akhiezer theorem hypotheses','arbitrary marked poles; unique up to proportionality','effective nonspecial degree-g divisor; uniqueness after leading coefficient 1 is fixed','The omitted divisor hypotheses and the normalization conflict are mathematical omissions in the notebook; Krichever1976 conditions1–2 supply the comparison.')

talk(380,'1976-02-09','V. G. Drinfeld','P000632-P000635','Algebraization by filtered modules','talk',r'Drinfeld begins beneath the end of Krichever\'s proof on P000633 and continues through P000634. He replaces an embedding of the punctured-curve function ring into differential operators by a filtered module and a connection-like operator. Gelfand\'s reciprocity and division-ring remarks are preserved as separate, underspecified programmes. The construction directly anticipates Drinfeld\'s 1977 note, which acknowledges the seminar context.')
item(380,'P000633','definition','Differential operator ring over a differential algebra',r'\(B\) is a commutative unital complex algebra with derivation \(b\mapsto b^{\prime}\); the ring \(B[D]\) has \(Db-bD=b^{\prime}\).',r'For any commutative unital \(\mathbb C\)-algebra \(B\) and derivation \(\delta\), the Ore extension \(B[D;\delta]\) consists of finite sums \(\sum b_iD^i\), with multiplication determined by \(Db=bD+\delta(b)\). This definition remains meaningful when \(B\) is not a field; existence of a division ring of fractions requires extra hypotheses.',r'The Ore-extension notation and the limitation about fractions are supplied; no analytic ellipticity is implicit in the ring definition.', 'E',r'The algebra is used explicitly in \citet[\S2]{drinfeld1977commutative}. The defining construction is background, distinct from the new geometric interpretation.',[DRI],area='Noncommutative algebra',literal_correctness='correct')
item(380,'P000633','claim','The claim that all commutative subrings come from smooth curves',r'With \(A=H^0(X\setminus\{P\},\mathcal O_X)\), the notes say that no other commutative subrings occur and attribute this to Shabat.',r'The smooth-curve formulation is too broad without restrictions. For example, the commutative subring \(\mathbb C[D^2,D^3]\subset\mathbb C[D]\) has a cuspidal spectrum; it is not the function ring of a smooth affine curve. Geometric classifications must allow singular spectral curves and suitable torsion-free sheaves, or restrict to subrings with a specified smooth spectral curve and regularity properties.',r'The cusp example is a direct counterexample to the unrestricted literal reading; it does not disprove a more qualified theorem that the speaker may have intended.', 'F',r'\citet[\S2]{drinfeld1977commutative} treats a fixed smooth pointed curve, while \citet[\S2, Main Theorem]{mulase1990geometric} explicitly allows singular curves. Searches did not identify an exact Shabat theorem with the notebook\'s stated quantifiers.',[DRI,MUL],area='Noncommutative algebra',literal_correctness='false as written',publication_match='partial',verification='unresolved lead',confidence='medium',present_status=r'As of 10 November 2026, the literal claim is false and the intended attribution remains unresolved; this is not evidence of an open classification problem.')
item(380,'P000633','remark','A noncommutative reciprocity programme',r'Gelfand describes the goal as a noncommutative reciprocity law.',r'No base field, arithmetic objects, reciprocity map or functorial conditions are stated. The connection with commutative subrings is a guiding analogy, not a formulated reciprocity theorem.',r'No later Langlands statement or Drinfeld-module theorem is read back into the phrase.', 'F',r'\citet[\S3]{drinfeld1977commutative} does pass to characteristic-\(p\) elliptic modules, but this thematic link does not identify or solve the unspecified reciprocity request.',[DRI],area='Arithmetic geometry',speaker='I. M. Gelfand (intervention)',literal_correctness='not determinable',publication_match='thematic only',verification='unresolved lead',present_status=r'As of 10 November 2026, the remark has no recoverable theorem-level formulation.')
item(380,'P000633','question','Extensions of Gelfand-Kirillov division rings',r'Gelfand calls the real problem finding all extensions of Gelfand--Kirillov division rings, adding that polynomiality is an obstacle.',r'The notebook does not say whether an extension means an embedding into a fixed division algebra, a finite-dimensional division-ring extension, an extension of the center, or a change in the number of Weyl pairs. Those choices give different problems. No exact classification question can be extracted without choosing information absent from the page.',r'The item is deliberately not identified with the fixed-rank Dixmier conjecture or with the Gelfand--Kirillov conjecture for enveloping algebras.', 'F',r'The historical division-ring framework is \citet[Introduction and \S1]{gelfandkirillov1966corps}. Searches combining Drinfeld, extensions and Gelfand--Kirillov division rings did not resolve the missing quantifiers.',['gelfandkirillov1966corps'],area='Noncommutative algebra',speaker='I. M. Gelfand (intervention)',literal_correctness='not determinable',publication_match='thematic only',verification='unresolved lead',present_status=r'As of 10 November 2026, this is an unresolved identification of a question, not a justified claim that a particular mathematical problem is open.')
item(380,'P000633','definition','Elliptic homomorphisms and their rank',r'Every nonzero image \(\varphi(a)\) is required to have an invertible leading coefficient. The notes derive \(\operatorname{ord}\varphi(a)=n\deg_P(a)\) and call \(n\) the rank.',r'Let \(X\) be a smooth connected projective complex curve, \(P\in X\), and \(A=H^0(X\setminus\{P\},\mathcal O_X)\). A unital \(\mathbb C\)-homomorphism \(\varphi:A\to B[D]\) is a Krichever homomorphism if every nonzero image has unit leading coefficient and some image has positive order. Then \(\operatorname{ord}\varphi(a)=n(-v_P(a))\) for nonconstant \(a\), with an integer \(n>0\). Because the pole-order semigroup is cofinite, \(n\) equals the greatest common divisor of the positive operator orders.',r'The nontrivial positive-order condition, smooth connected curve and meaning of degree are made explicit. Elliptic here is algebraic terminology, not a real principal-symbol positivity condition.', 'A',r'The definition and rank lemma occur in \citet[\S2, preceding Proposition 2]{drinfeld1977commutative}, received 14 April 1976 and published in 1977.',[DRI],area='Algebraic geometry')
item(380,'P000633-P000634','construction','A homomorphism encoded by a filtered module',r'Take \(M=B[D]\), let \(B\) act on the left and \(A\) on the right through \(\varphi\), filter by operator order, and let \(\nabla\) be left multiplication by \(D\).',r'The filtration has \(M_{-1}=0\), \(M=\bigcup_{i\ge0}M_i\), and each \(M_i/M_{i-1}\) is free of rank one over \(B\). The operator \(\nabla\) commutes with \(A\), satisfies \(\nabla(bm)=b\nabla m+b^{\prime}m\), and induces isomorphisms on successive graded pieces. A nonzero \(a\in A\) shifts filtration by \(n\deg_P(a)\) and gives a graded isomorphism. Conversely, these axioms and a generator of \(M_0\) identify \(M\) with \(B[D]\) and recover the right multiplication homomorphism, up to invertible scalar gauge.',r'Exhaustiveness, the initial zero piece and local freeness are stated explicitly; the converse follows by induction on filtration degree.', 'A',r'\citet[Proposition 2 and its proof]{drinfeld1977commutative} gives the precise module correspondence.',[DRI],area='Algebraic geometry')
item(380,'P000634','method','From order filtrations to sheaves and a pole at infinity',r'The filtered \(A\otimes B\)-module is reinterpreted as a sheaf on \(X\) with a filtration, and \(\nabla\) as a connection singular at infinity.',r'A compatible exhaustive good filtration on a finite-type \(A\otimes B\)-module allows extension across \(P\) by lattices determined by pole order. For rank one and a nonsingular spectral curve, the regular geometric case gives a line bundle and an \(\mathcal O_X\)-linear relative operator \(\nabla:L\to L(P)\) obeying the \(B\)-Leibniz rule. Arbitrary filtered modules without the freeness, growth and multiplication-isomorphism conditions need not define this geometric object.',r'The word connection means differentiation in the coefficient parameter, not a flat holomorphic connection on all tangent directions of the curve.', 'A',r'The exact extension machinery is \citet[Proposition 1, Corollary 1, and Proposition 2]{drinfeld1977commutative}; the March talks unpack its rank-one case.',[DRI],area='Algebraic geometry')
BRO='brodskii1976spectral';PSU='paternainsalouhlmann2022geometric';HAL='halperintoledo1972stiefel';GAR='garcia1972connections'
talk(381,'1976-02-23','S. P. Novikov','P000633-P000636','Brodskii radial spectral inversion; Fuchs on characteristic cycles','talk',r'P000635 explicitly describes Novikov reporting work of M. Brodskii of Minsk; the matching author is M. A. Brodskii. The radial spectral problem, semiclassical action and Abel inversion match his 1976 two-page note, received on 18 June 1975. Receipt establishes submission chronology, not prior public circulation. The B classification records that the named author differs from the reporter; it does not mean that Brodskii developed an idea of Novikov\'s after the seminar. Fuchs then intervenes on Stiefel--Whitney cycles before Losik begins at the bottom of the page.')
radial=item(381,'P000635','problem','Recovering a radial profile from its joint frequency array',r'For an elastic sphere, recover the medium parameter from all \(\lambda_{k\ell}\). The written equation contains both a \(\lambda^2 f^2\) term and a separate eigenvalue on the right, with an inconsistent sign.',r'The identified scalar radial model is \(y^{\prime\prime}+[\lambda_{k\ell}^2f(r)^2-\ell(\ell+1)/r^2]y=0\), \(0<r<1\). Require the regular solution at zero and a fixed real homogeneous separated condition \(\alpha y(1)+\beta y^{\prime}(1)=0\), \((\alpha,\beta)\ne(0,0)\). For the monotone reconstruction assume \(f>0\), \(f(1)=1\), and \(q(r)=rf(r)\) strictly increasing from zero to one; smoothness and \(q^{\prime}>0\) suffice for the formulas below. The data retain both radial and angular indices. This scalar equation does not recover every Lam\'e parameter of an arbitrary elastic solid.',r'The corrected equation and endpoint conditions come from the identified publication. Positivity and strict smooth monotonicity delimit a regular version; the notebook writes only monotonicity and omits boundary conditions.', 'B',r'\citet[equations (1)--(2) and Theorem 2]{brodskii1976spectral} is the exact publication match for the reported scalar problem, published in volume 31(4), 1976.',[BRO],area='Inverse problems',literal_correctness='false as written',problem='GP-1975-13')
item(381,'P000635','method','Semiclassical spectral sampling of the radial action',r'With \(q=rf\) monotone, the notes use a turning point \(H(\tau)\), an action integral, and pairs \(\tau_{k\ell}=\sqrt{\ell(\ell+1)}/\lambda_{k\ell}\), \(m_{k\ell}=(k+1/4+C)/\sqrt{\ell(\ell+1)}\).',r'For \(\ell\ge1\), write \(L_\ell=\sqrt{\ell(\ell+1)}\), \(H=q^{-1}\), and \[m(\tau)=\pi^{-1}\int_{H(\tau)}^1\sqrt{\tau^{-2}f(r)^2-r^{-2}}\,dr,\qquad 0<\tau<1.\] In the smooth one-turning-point regime, the leading quantization relation samples this action as \(m(\tau_{k\ell})=(k+\delta_{k\ell})/L_\ell+o(1)\) along joint high-frequency limits in compact interior \(\tau\)-ranges. The bounded phase \(\delta_{k\ell}\) depends on the endpoint condition; it is not a universal constant. Dense limiting ratios recover the continuous action curve.',r'The factor \(1/\pi\), bounded boundary phase, limiting interpretation and interior restriction are supplied. Individual finite-index pairs are not asserted to lie exactly on a smooth dispersion graph.', 'B',r'\citet[Theorem 1 and equation (4)]{brodskii1976spectral} supplies the asymptotic sampling, with the boundary correction retained explicitly.',[BRO],area='Inverse problems',literal_correctness='false as written',problem='GP-1975-13')
item(381,'P000635','method','The Abel inversion and its missing normalization',r'The inverse \(\psi=q^{-1}\) is written as an exponential with coefficient 2 and kernel \((\tau^2-\eta^2)^{-1/2}\); the lower endpoint is absent. The preceding action integral lacks \(1/\pi\).',r'For positive smooth \(f\) with \(q(0)=0\), \(q(1)=1\), \(q^{\prime}>0\), let \(M(\tau)=\tau m(\tau)\) with the normalized action of the previous item. Then for \(0<\eta<1\), \[\log\psi(\eta)=2\int_\eta^1\frac{M^{\prime}(\tau)}{\sqrt{\tau^2-\eta^2}}\,d\tau.\] If the notebook\'s unnormalized action is retained, the multiplier must instead be \(2/\pi\). Knowing \(\psi\) recovers \(q\) by inversion and \(f(r)=q(r)/r\).',r'The lower endpoint and normalization are emendations. They were checked by composing the two Abel kernels and independently with the constant profile; the bounded check is recorded in the research log.', 'E',r'\citet[Theorem 2, equations (5)--(6)]{brodskii1976spectral} gives this application. The Abel inversion mechanism is classical; \citet[Theorems 2.2.1 and 2.2.3, historical Remark 2.2.2]{paternainsalouhlmann2022geometric} distinguishes the older Herglotz travel-time inversion from Brodskii\'s spectral sampling.',[BRO,PSU],area='Inverse problems',literal_correctness='false as written',publication_match='partial',problem='GP-1975-13')
item(381,'P000635','question','Compatibility of an overdetermined spectral array',r'The source calls the inverse problem overdetermined and asks when it is solvable; it mentions density and a one-to-one relation between spectral parameters.',r'For the fixed radial boundary problem above, a necessary condition is that its joint high-frequency samples approach a continuous monotone action/dispersion graph compatible with a positive increasing inverse profile. Such leading asymptotic compatibility is not sufficient for an arbitrary entire array to equal the exact spectrum of that profile: finitely many modified eigenvalues leave the limiting graph unchanged but may violate exact spectral constraints.',r'The last observation separates a range theorem for a leading action transform from a range theorem for all exact frequencies. The notebook does not specify a complete topology, boundary model or list of sufficient conditions.', 'B',r'\citet[corollary after Theorem 2]{brodskii1976spectral} states a necessary condition, not a full necessary-and-sufficient spectral-range theorem. No claim that the whole range question was solved is made here.',[BRO],area='Inverse problems',publication_match='partial',literal_correctness='not determinable',problem='GP-1975-13',present_status=r'As of 10 November 2026, the identified publication establishes the stated necessary compatibility and inversion results. The notes are insufficient to isolate an additional exact residual range problem, so no C classification is manufactured from the omitted endpoint data.')
item(381,'P000635','theorem','Barycentric cycles representing Stiefel-Whitney classes',r'Fuchs observes that the sum of all edges of an arbitrary triangulation need not be a mod-two cycle, whereas it is a cycle after first barycentric subdivision; the dual classes are Stiefel--Whitney classes.',r'Let \(K\) be a smooth finite triangulation of a closed smooth \(n\)-manifold \(M\), and let \(K^{\prime}\) be its first barycentric subdivision. For each \(0\le p\le n\), the sum \(c_p\) of all \(p\)-simplices of \(K^{\prime}\), with coefficients in \(\mathbb F_2\), is a cycle and \([c_p]=w_{n-p}(TM)\cap[M]\). In particular, the all-edge cycle represents the homology class dual to \(w_{n-1}\), not generally to \(w_1\). For manifolds with boundary a relative formulation is needed.',r'The dimension indexing and closed-manifold hypotheses are reconstructed. The notebook drawings support the parity motivation but do not replace the characteristic-class theorem.', 'E',r'The precise mod-two statement was published in \citet[Theorem 1 and its corollary, pp.~511--512]{halperintoledo1972stiefel}; their remarks also discuss the PL extension.',[HAL],area='Topology',speaker='D. B. Fuchs (intervention)')
item(381,'P000635','claim','Parity of the simplex count and Euler characteristic',r'Fuchs concludes that modulo two the sum of simplex counts equals the alternating sum, hence the Euler characteristic.',r'For a finite triangulation \(K\), \(\sum_i f_i(K)\equiv\sum_i(-1)^if_i(K)=\chi(|K|)\pmod2\). The vertices of \(K^{\prime}\) correspond to nonempty simplices of \(K\), so its all-vertex zero-cycle has augmentation \(\chi(M)\bmod2\). For a closed \(n\)-manifold this is \(\langle w_n(TM),[M]\rangle\). Finiteness is essential to the elementary numerical sum.',r'The link between vertices of the subdivision and original simplices explains the otherwise compressed final line.', 'E',r'\citet[\S1, discussion of \(C_0\), p.~512]{halperintoledo1972stiefel} identifies this zero-dimensional case with the Euler characteristic.',[HAL],area='Topology',speaker='D. B. Fuchs (intervention)',literal_correctness='correct')
problem('GP-1975-13','Monotone radial profile from the indexed frequency matrix',r'Recover the positive radial coefficient \(f\) of \(y^{\prime\prime}+[\lambda_{k\ell}^2f^2-\ell(\ell+1)/r^2]y=0\), with regular origin and fixed separated outer boundary condition, from its fully indexed spectrum, assuming \(rf\) is strictly increasing and normalized at the outer radius.',[radial,'1975-381.2','1975-381.3','1975-381.4'],r'As of November 2026, the reported monotone reconstruction is identified with Brodskii1976, Theorems1–2; its Abel inversion is classical. The accompanying necessary spectral compatibility condition is not advertised as a full characterization of exact arrays.',[BRO,PSU])
correction('P000635','radial eigenvalue equation',r'\(-y^{\prime\prime}+(\lambda^2f^2-\ell(\ell+1)/r^2)y=\lambda_{k\ell}y\)',r'\(y^{\prime\prime}+[\lambda_{k\ell}^2f^2-\ell(\ell+1)/r^2]y=0\)','The scan matches the diplomatic text, so this is not OCR repair. Brodskii1976 title and equation(2), and the immediately following turning-point integral, identify the intended equation.')
correction('P000635','action normalization and inverse integral','action integral has no 1/pi; inverse exponential coefficient is 2 with no lower limit','insert 1/pi in the action and eta as lower limit; alternatively retain the action and replace 2 by 2/pi','The scan omits both 1/pi and the lower endpoint. Brodskii1976 equations(3),(5), and the independently checked Abel-kernel composition determine the correction.')
correction('P000635','spectral interpolation equality','the finite spectral pairs define an exact single-valued correspondence','read as joint high-frequency asymptotic sampling with boundary-dependent phase','The scan gives a literal equality. Brodskii1976 Theorem1 is explicitly asymptotic; its corollary supplies only a necessary compatibility condition.',typ='faithful_error')

talk(382,'1976-02-23','M. V. Losik','P000634-P000638','The affine bundle of connections and its universal connection','talk',r'Losik begins at the bottom of P000635 and continues through P000637. Starting from frames and a principal connection form, he constructs the finite-dimensional affine bundle whose sections are connections, then the tautological connection on the pulled-back principal bundle. Gabrielov identifies the model vector bundle. The construction predates the talk in Garc\'ia\'s 1972 paper; a mistaken base space in the notes is corrected.')
item(382,'P000635-P000636','definition','Frame bundle and vertical Maurer-Cartan identification',r'For a real rank-\(n\) bundle \(E\to X\), a frame \(z\) is multiplied on the right by \(A\in GL(n,\mathbb R)\). Differentiating the orbit map identifies the vertical tangent space with the Lie algebra.',r'For a smooth rank-\(n\) real vector bundle, its frame bundle \(P=\operatorname{Fr}(E)\) is a principal right \(GL(n,\mathbb R)\)-bundle. At \(z\in P_x\), the fundamental-vector map \(\alpha_z:\mathfrak{gl}_n\to V_zP\), \(\xi\mapsto\left.\frac{d}{dt}\right|_0 z\exp(t\xi)\), is an isomorphism; write \(\beta_z=\alpha_z^{-1}\). The action is free and transitive within each fiber, not on the whole frame bundle.',r'The right-action convention and distinction between a fiber and the total space are supplied explicitly.', 'E',r'This principal-bundle framework underlies \citet[\S\S2--3]{garcia1972connections}; the source paper predates the seminar by four years.',[GAR],area='Differential geometry',literal_correctness='correct')
item(382,'P000636','definition','Connection forms and equivariant horizontal complements',r'A connection form \(\omega\) restricts to \(\beta_z\) vertically and satisfies \(R_A^*\omega=\operatorname{Ad}(A^{-1})\omega\). Its kernel is the horizontal space.',r'For a smooth principal right \(G\)-bundle, a principal connection is a \(\mathfrak g\)-valued one-form \(\omega\) satisfying \(\omega(\xi^\#)=\xi\) and \(R_g^*\omega=\operatorname{Ad}_{g^{-1}}\omega\). Equivalently, \(TP=H\oplus VP\) with a smooth \(G\)-equivariant horizontal subbundle. For a frame bundle this corresponds to a linear connection on \(E\); the induced tangent-bundle connection is not automatically torsion-free.',r'The word affine in the notes is read as a connection on the tangent/frame bundle, without adding a torsion-free condition.', 'E',r'Compare the connection-form and horizontal-distribution formulations used in \citet[\S3, proof of Theorem 3]{garcia1972connections}.',[GAR],area='Differential geometry',literal_correctness='correct')
item(382,'P000636-P000637','construction','Affine fibers of pointwise connection data',r'At \(z\), the space \(C_z\) of forms restricting to \(\beta_z\) is an affine plane parallel to the space \(\Theta_z\) of forms vanishing on vertical vectors.',r'Define \(C_z=\{\eta\in\operatorname{Hom}(T_zP,\mathfrak g):\eta|_{V_zP}=\beta_z\}\) and \(\Theta_z=\operatorname{Hom}(T_zP/V_zP,\mathfrak g)\). Then \(C_z\) is an affine space modeled on \(\Theta_z\); subtraction of two elements is well defined, but there is no distinguished zero. The union \(C(P)\to P\) is a smooth affine bundle with its induced \(G\)-action.',r'The affine-torsor distinction is explicit: choosing one connection identifies fibers with vector spaces, but the identification is not canonical.', 'E',r'The equivalent jet construction occurs in \citet[\S2, Theorems 1--2]{garcia1972connections}.',[GAR],area='Differential geometry')
item(382,'P000637','theorem','Connections as sections of an affine bundle over the base',r'The quotient \(B(P)=C(P)/G\) is formed; connections correspond to its sections.',r'For a smooth principal \(G\)-bundle \(P\to X\), let \(\mathcal C(P)=C(P)/G\). Smooth sections \(s:X\to\mathcal C(P)\) correspond bijectively to principal connections on \(P\): the equivariant lift chooses \(\omega_z\in C_z\) at every frame. Its affine model is \(T^*X\otimes\operatorname{ad}P\), where \(\operatorname{ad}P=P\times_G\mathfrak g\). For \(P=\operatorname{Fr}(E)\), this is \(T^*X\otimes\operatorname{End}(E)\).',r'The symbol \(\mathcal C(P)\) avoids confusing the quotient with the affine bundle over \(P\). The adjoint bundle, not a fixed global copy of \(\mathfrak g\), is necessary.', 'E',r'\citet[Theorem 2, p.~236]{garcia1972connections} proves the section/connection correspondence.',[GAR],area='Differential geometry')
item(382,'P000637','construction','The tautological universal connection and its correct base',r'The notes call \(C(P)\) a principal bundle with a canonical connection, but state its base as \(P\).',r'The principal bundle is \(C(P)\to\mathcal C(P)=C(P)/G\), naturally isomorphic to the pullback of \(P\to X\) along \(\mathcal C(P)\to X\). If \(p:C(P)\to P\), define \(\Omega_{(z,\eta)}(V)=\eta(dp(V))\). This reproduces fundamental vertical fields and is \(G\)-equivariant, hence is a principal connection. Pullback by the equivariant lift of a section \(s\) recovers precisely the connection represented by \(s\). The map to \(P\) has affine fibers and is not the asserted principal \(G\)-bundle.',r'The base-space correction and evaluation formula make the universal property precise; they are the intrinsic content of the displayed construction.', 'E',r'This is the canonical connection of \citet[Theorem 3, pp.~238--240]{garcia1972connections}, expressed in pointwise connection data instead of jets.',[GAR],area='Differential geometry',literal_correctness='false as written')
item(382,'P000637','remark','Difference of connections as an endomorphism-valued one-form',r'Gabrielov identifies the affine model, first writing a fixed Lie-algebra factor and then \(T^*X\otimes\operatorname{Hom}(E,E)\).',r'If \(\nabla_1,\nabla_2\) are linear connections on the same smooth vector bundle \(E\), their difference is \(C^\infty(X)\)-linear in the section and is a one-form in its vector argument: \(\nabla_1-\nabla_2\in\Omega^1(X;\operatorname{End}E)\). Conversely, adding any such one-form to a connection produces another connection. A fixed global \(\mathfrak{gl}_n\) coefficient space is valid only after a global trivialization of the adjoint bundle.',r'The final corrected bundle expression is retained; the crossed-out trivial coefficient bundle is not silently promoted to a global assertion.', 'E',r'The affine structure is part of \citet[\S2, Theorem 2]{garcia1972connections}; its local Christoffel-symbol version is standard background.',[GAR],area='Differential geometry',speaker='A. M. Gabrielov (intervention)',literal_correctness='correct')
correction('P000637','base of the canonical principal bundle','C(P) is a principal bundle with base P','C(P) is a principal G-bundle with base C(P)/G; its map to P is affine','The scan and Russian text name P. The displayed G-orbit construction and García1972 Theorems1–3 show the correct quotient base.')

FOR='forster1981riemann'
talk(383,'1976-03-01','S. P. Novikov','P000636-P000640','Pointed curves, pole orders and the rank-one correspondence','talk',r'The catalogue attributes this record to Novikov, but the dated manuscript heading on P000638 explicitly names Drinfeld (Volodya). The mathematical discussion continues through P000641. This provenance discrepancy is retained rather than silently correcting the catalogue. Gelfand and Krichever contribute curve examples and pole-order remarks; S. Gelfand gives a separate divisor explanation on P000639. The main line passes from rings of functions on a pointed curve to filtered modules and acyclic line bundles.')
item(383,'P000638','construction','Pointed-curve rings and their genus-zero and elliptic examples',r'For a smooth projective curve and marked point, the ring consists of rational functions regular off that point. The examples are a genus-zero conic and \(y^2=x(x-1)(x-2)\), with pole orders two and three for \(x,y\). The latter are identified literally with \(\wp,\wp^{\prime}\).',r'Let \(X\) be a smooth connected projective complex curve, \(P\in X\), and \(A=H^0(X\setminus\{P\},\mathcal O_X)\). For \((X,P)=(\mathbb P^1,\infty)\), \(A=\mathbb C[z]\). For the smooth projective completion of the displayed cubic and its point at infinity, \(A=\mathbb C[x,y]/(y^2-x(x-1)(x-2))\), with pole orders two and three. With \((\wp^{\prime})^2=4\wp^3-4\wp\), its correctly normalized uniformization is \(x=1+\wp\), \(y=\wp^{\prime}/2\). A genus-one curve has no nonconstant function with a unique simple pole, because that would define a degree-one map to \(\mathbb P^1\).',r'\oursComputed\ The normalization follows by substituting \(x=1+w\) into the cubic. The degree-one-map argument supplies the reason behind the notebook\'s torus remark; no new uniformization theorem is asserted.', 'E',r'These are classical curve examples. The later exposition \citet[Ch.~II]{forster1981riemann} is cited for context; only its publisher record and author\'s contents were checked.',[FOR],area='Algebraic geometry',speaker='Gelfand (intervention; initial only)',literal_correctness='false as written',publication_match='partial',verification='publisher metadata checked')
item(383,'P000638','question','Recovering the pointed curve from its punctured function ring',r'The ring is said to determine the curve and the point uniquely, followed by the question how to describe all such rings.',r'The rings in question are precisely the finitely generated integrally closed complex domains of transcendence degree one whose smooth projective completion has exactly one point outside its affine spectrum. An isomorphism of such complex algebras identifies their function fields and affine curves, hence their unique smooth projective completions and the omitted points. The one-point condition is necessary: a general smooth affine curve may have several punctures.',r'The finite-generation, normality, transcendence-degree and one-point conditions are explicit reconstruction of the broad algebraic question. No intrinsic finite list of generators and relations is being claimed.', 'E',r'This is the classical affine/projective correspondence for nonsingular curves; \citet[\S1]{drinfeld1977commutative} uses the fixed pointed-curve ring, without claiming the underlying correspondence as new.',[DRI],area='Algebraic geometry',speaker='V. G. Drinfeld (manuscript heading)',publication_match='thematic only')
item(383,'P000638','theorem','Weierstrass gaps and the residue-class formula',r'Krichever says that a general point has least pole order \(g+1\); a hyperelliptic branch point permits order two. If \(n\) is the least positive order and \(s+\mu_sn\) the least order in residue class \(s\), then \(\sum_{s=1}^{n-1}\mu_s=g\).',r'For a smooth connected projective complex curve of genus \(g\), the pole-order semigroup \(H(P)\subset\mathbb Z_{\ge0}\) has exactly \(g\) positive gaps. At a non-Weierstrass point they are \(1,\ldots,g\). If \(n\) is its least positive nongap and \(s+\mu_sn\) is the least nongap congruent to \(s\pmod n\), then the gaps in that residue class are \(s,s+n,\ldots,s+(\mu_s-1)n\); consequently the asserted sum equals \(g\). On a smooth hyperelliptic curve of genus at least one, a branch point has a degree-two function with its only pole there. The hyperelliptic polynomial must have distinct roots.',r'The residue-class count explains the formula directly once the classical gap theorem is used. The genus and smoothness qualifications exclude degenerations hidden by the abbreviated equation.', 'E',r'This is classical Riemann--Roch/Weierstrass-gap theory; see the later textbook context \citet[Ch.~II, \S\S16--18]{forster1981riemann}. The full textbook was not accessible.',[FOR],area='Algebraic geometry',speaker='I. M. Krichever (intervention)',verification='publisher metadata checked')
item(383,'P000639','claim','Generators at an ordinary point and the missing generator',r'The notes say there are \(g\) generators, then list orders \(g+1,g+2,\ldots,2g+1\).',r'At a non-Weierstrass point of a genus-\(g\) smooth projective complex curve, choose functions with unique poles of orders \(g+1,\ldots,2g+1\), one for each order. These \(g+1\) functions generate \(A\). Indeed those integers generate the nongap semigroup: an order above \(2g+1\) can repeatedly be reduced by \(g+1\). A monomial with the same pole order as a given function can be scaled to cancel its leading term; induction reduces the remainder to a constant. This asserts a generating set, not an unconditional minimal number of algebra generators.',r'\ours\ The short leading-term induction is supplied to justify the emended count. It also includes genus zero, when the single generator has order one.', 'E',r'The claim is an elementary consequence of the classical gap structure recalled in \citet[Ch.~II]{forster1981riemann}; the induction here is explicit reconstruction.',[FOR],area='Algebraic geometry',speaker='V. G. Drinfeld (manuscript heading)',literal_correctness='false as written',publication_match='partial',verification='publisher metadata checked')
item(383,'P000639','definition','Elliptic homomorphisms and the pole/order rank revisited',r'The differential algebra \(B[D]\), invertible leading coefficients, and the integer relation \(\operatorname{ord}\varphi(a)=n\deg_P a\) are recalled.',r'For the pointed-curve ring \(A\), a commutative differential complex algebra \((B,\delta)\), and the Ore relation \(Db-bD=\delta(b)\), require \(\varphi:A\to B[D]\) to be unital, nontrivial in positive order, and to have unit leading coefficient for every nonzero image. Then its orders are a fixed positive integer multiple of pole orders, as in item 1975-380.5. The rank is that integer, not the degree of a chosen generator alone.',r'The nonzero qualifier and positive-order requirement, omitted in the shorthand, are retained from the precise definition.', 'A',r'\citet[\S2, definition and rank lemma]{drinfeld1977commutative} gives the matching formulation.',[DRI],area='Algebraic geometry',speaker='V. G. Drinfeld (manuscript heading)')
item(383,'P000639','remark','The order-two/order-three commuting example recalled',r'Gelfand interjects that commuting differential operators of orders two and three exist.',r'The operators \(D^2-2u\) and \(D^3-3uD-3u^{\prime}/2\) commute when \(u^{(3)}=12uu^{\prime}\); elliptic functions satisfying \((u^{\prime})^2=4u^3-g_2u-g_3\), and their degenerations, provide examples. Coefficients are taken locally away from poles. This is the earlier school exercise in another sign convention.',r'The explicit pair makes the bare existence remark precise; the example is classical.', 'E',r'\citet[\S3, equations (2)--(3)]{mulase1990geometric} records the example and its early history.',[MUL],area='Integrable systems',speaker='I. M. Gelfand (intervention)',literal_correctness='correct',problem='GP-1975-12')
item(383,'P000639','claim','Leading coefficient and dependence on the local parameter',r'For \(a=z^{-k}+\cdots\), the notes give \(\varphi(a)=b^kD^{nk}+\cdots\) and say that \(b\) is independent of \(k\) and of the chosen local parameter.',r'With \(z\) fixed and the rank hypotheses above, a unique \(b\in B^*\) gives the normalized leading coefficients \(b^k\). The pole-order semigroup is cofinite, and multiplicativity makes the leading-coefficient homomorphism extend to its group completion \(\mathbb Z\). However, if \(\widetilde z=cz+O(z^2)\), \(c\ne0\), then \(\widetilde b=c^{-1}b\). Thus the scalar coefficient is not coordinate invariant. The corresponding tangent-direction datum, with the appropriate reciprocal coordinate factor, is intrinsic.',r'\oursComputed\ The rescaling follows by replacing the normalized function by \(c^{-k}a\); the notebook\'s claim of independence of the parameter is emended.', 'A',r'The intrinsic principal-part datum is used in \citet[Corollary 2]{drinfeld1977commutative}.',[DRI],area='Algebraic geometry',speaker='V. G. Drinfeld (manuscript heading)',literal_correctness='false as written',publication_match='partial')
item(383,'P000639','definition','Gauge equivalence and local removal of a scalar connection term',r'Two homomorphisms are equivalent under conjugation by \(b\in B^*\); the notes write \(D\sim D+b^{\prime}/b\), with an arbitrary function obtainable as a logarithmic derivative among germs.',r'For a smooth nonvanishing complex function germ \(h\), \(h^{-1}Dh=D+h^{-1}h^{\prime}\), while \(hDh^{-1}=D-h^{-1}h^{\prime}\). The equivalence relation allows either orientation. Every smooth complex germ \(a\) is a logarithmic derivative of a unit germ, by solving \(h^{\prime}=ah\) with \(h(0)\ne0\). This local statement does not imply a periodic or global gauge exists.',r'The conjugation orientation is made explicit. There is no sign correction to the notebook\'s symmetric equivalence symbol.', 'E',r'The equivalence relation appears in \citet[\S2]{drinfeld1977commutative}; its scalar differential calculation is elementary background.',[DRI],area='Differential equations',speaker='V. G. Drinfeld (manuscript heading)',literal_correctness='correct')
rankone=item(383,'P000639','theorem','Rank-one homomorphisms from a leading coefficient and a Jacobian point',r'For germs of smooth functions on the line, rank-one homomorphisms up to equivalence correspond to their leading coefficient and a point of the Jacobian.',r'Fix \((X,P,z)\) and let \(B\) be the algebra of smooth complex-valued germs at \(x=0\), with \(D=d/dx\). Rank-one Krichever homomorphisms \(A\to B[D]\), modulo unit scalar conjugation, correspond to pairs \((L_0,b)\), where \(b\in B^*\) and \(L_0\in\operatorname{Pic}^{g-1}(X)\) satisfies \(H^0(X,L_0)=H^1(X,L_0)=0\). The allowed line bundles form the complement of the theta divisor. Identifying this torsor with \(\operatorname{Jac}(X)=\operatorname{Pic}^0(X)\) requires a reference line bundle of degree \(g-1\). The construction is local in the coefficient parameter.',r'The acyclic open subset, torsor identification, and germ setting are essential qualifications; an arbitrary point of the full Jacobian is not admissible.', 'A',r'\citet[Corollary 2]{drinfeld1977commutative} gives this precise correspondence, attributing it to Krichever.',[DRI],area='Algebraic geometry',speaker='V. G. Drinfeld (manuscript heading)',problem='GP-1975-14')
item(383,'P000640','construction','Recovering the homomorphism from a cyclic filtered module',r'The module construction is repeated in rank one. The first quotient is written \(M_i/M_{i+1}\), despite the increasing filtration; subsequent displays use \(M_i/M_{i-1}\). A generator \(e\in M_0\) recovers the differential operator realization.',r'Use an exhaustive filtration \(0=M_{-1}\subset M_0\subset\cdots\), with each \(M_i/M_{i-1}\) a free rank-one \(B\)-module. Require the graded multiplication by \(a\ne0\) to shift by \(\deg_Pa\) isomorphically, and an \(A\)-linear operator \(\nabla\) with the \(B\)-Leibniz rule and isomorphisms between adjacent graded pieces. For a generator \(e\in M_0\), \(e,\nabla e,\ldots,\nabla^ie\) form a \(B\)-basis of \(M_i\), identifying \(M\) with \(B[D]\). The commuting \(A\)-action is right multiplication by the recovered \(\varphi(a)\); another generator changes only its scalar gauge class.',r'The backward quotient is corrected, dimension over a possibly non-field is replaced by free rank, and the inductive meaning of the notebook\'s put \(D=\nabla(e)\) is specified.', 'A',r'\citet[Proposition 2, proof]{drinfeld1977commutative} formalizes this argument.',[DRI],area='Algebraic geometry',speaker='V. G. Drinfeld (manuscript heading)',literal_correctness='false as written')
item(383,'P000640-P000641','construction','Acyclic line bundles produce the pole filtration',r'The filtration corresponds to a line bundle with vanishing zeroth and first cohomology, and \(M_i\) consists of sections with pole order at most \(i+1\) at \(P\).',r'For a line bundle \(L\) on the smooth projective complex curve \(X\), assume \(H^0(X,L)=H^1(X,L)=0\). Then \(\deg L=g-1\). Put \(M=H^0(X\setminus\{P\},L)\), \(M_i=H^0(X,L((i+1)P))\) for \(i\ge-1\). The successive exact sequences at \(P\) and the vanishing of \(H^1(X,L)\) give \(\dim M_i=i+1\) and \(\dim M_i/M_{i-1}=1\) for \(i\ge0\). Over a coefficient algebra, use a locally free family with the corresponding cohomology and base-change conditions, not a tensor product of a fixed fiber assumed without justification.',r'The shift by one is retained exactly from the scan. The family qualification separates the displayed complex-vector-space argument from its relative version.', 'A',r'\citet[Proposition 1 and Corollary 1]{drinfeld1977commutative} supplies the relative sheaf statement.',[DRI],area='Algebraic geometry',speaker='V. G. Drinfeld (manuscript heading)')
item(383,'P000641','method','Reconstructing the line bundle on two affine charts',r'For nonconstant \(a_0\in A\), the cover is \((X\setminus P)\cup(X\setminus\operatorname{zeros}(a_0))\). On the second chart sections are \(m/a_0^k\), with \(m\in M_{k\deg(a_0)-1}\).',r'Let \(M\) have the rank-one exhaustive filtration and multiplication isomorphisms of the preceding items, and write \(d=\deg_Pa_0>0\). Over \(U=X\setminus\{P\}\) use the module \(M\); over \(V=X\setminus\operatorname{zeros}(a_0)\) use the union of fractions \(a_0^{-k}M_{kd-1}\) for \(k\ge0\), inside \(M[a_0^{-1}]\). On \(U\cap V\) both localize to \(M[a_0^{-1}]\), so they glue. The filtration axioms give the line bundle extending across \(P\); the bound \(kd-1\) precisely cancels the allowed pole of order \(kd\).',r'The common localization and union are supplied to make the notebook\'s chart formula unambiguous; local freeness relies on the earlier filtration hypotheses.', 'A',r'Compare the reconstruction proof in \citet[Proposition 1]{drinfeld1977commutative}.',[DRI],area='Algebraic geometry',speaker='V. G. Drinfeld (manuscript heading)')
correction('P000638','speaker in dated heading','catalogue record 383: S. P. Novikov','retain catalogue attribution but identify manuscript heading as Drinfeld (Volodya)','The scan explicitly reads Drinfeld (Volodya), dated 1/III-76; the catalogue and manuscript are distinct witnesses.',typ='provenance')
correction('P000638','elliptic uniformization',r'\(x=\wp(z), y=\wp^{\prime}(z)\) for \(y^2=x(x-1)(x-2)\)',r'\(x=1+\wp(z;4,0), y=\wp^{\prime}(z;4,0)/2\)','The scan has the unscaled formulas. Substitution into the Weierstrass equation supplies the necessary shift and scale.')
correction('P000639','number of generators at an ordinary point','g generators of orders g+1,...,2g+1','g+1 generators of those orders','The list in both the scan and transcription contains g+1 orders. The pole-order induction verifies the corrected generating set.')
correction('P000639','coordinate dependence of leading coefficient','b is independent of k and of the local parameter','b is independent of k for fixed parameter; z_tilde=c z+... gives b_tilde=c^{-1}b','The scan explicitly adds independence of parameter. Rescaling normalized Laurent leading terms disproves that addition.')
correction('P000640','first filtration quotient',r'\(\dim_B M_i/M_{i+1}=1\)',r'\(M_i/M_{i-1}\) is free of rank one over \(B\)','The scan has denominator M_{i+1}, incompatible with the displayed increasing filtration; every subsequent graded map uses M_{i-1}.')

talk(384,'1976-03-01','S. I. Gelfand','P000638-P000643','Divisors and the analytic Jacobian','talk',r'The explicitly labelled S. Gelfand intervention is the short explanation of degree-zero divisor classes at the foot of P000639. The next page labels the analytic Jacobian explanation only G.; that initial does not by itself distinguish S. I. from I. M. Gelfand. Its mathematical content is indexed here as the continuation of the explanatory intervention, with the attribution uncertainty stated. Drinfeld\'s filtered-module and sheaf construction, including all of P000641, remains with record 383.')
item(384,'P000639','definition','Degree-zero divisor classes and line bundles',r'S. Gelfand explains line bundles of degree zero as divisors \(\sum n_iQ_i\), \(\sum n_i=0\), modulo divisors of meromorphic functions.',r'For a smooth connected projective complex curve, every line bundle admits a nonzero meromorphic section. Sending a divisor \(D\) to \(\mathcal O_X(D)\) identifies divisors modulo principal divisors with \(\operatorname{Pic}(X)\), and identifies degree-zero classes with \(\operatorname{Pic}^0(X)\). Changing the meromorphic section changes its divisor by a principal divisor, so its class is unchanged.',r'The all-line-bundle statement is included only to explain the degree-zero restriction; it does not identify line bundles of different degree.', 'E',r'This is classical divisor theory; \citet[Ch.~II, \S20 and Ch.~III, \S29]{forster1981riemann} is a later reference whose contents were checked.',[FOR],area='Algebraic geometry',literal_correctness='correct',verification='publisher metadata checked')
item(384,'P000640','definition','The period lattice and the analytic Jacobian',r'The analytic definition uses \(g\) holomorphic differentials and \(2g\) period vectors, yielding \(\mathbb C^g/\Lambda\). On a smooth elliptic cubic, \(dx/y\) has no singularities even at branch points. Only some complex tori arise in this manner.',r'For a compact connected Riemann surface of genus \(g\), \(V=H^0(X,\Omega_X^1)\) has complex dimension \(g\). Integration embeds \(H_1(X,\mathbb Z)\) as a lattice \(\Lambda\subset V^*\) of rank \(2g\); \(\operatorname{Jac}(X)=V^*/\Lambda\), canonically isomorphic to \(\operatorname{Pic}^0(X)\). On the nonsingular completion of \(y^2=x(x-a)(x-b)\), \(ab(a-b)\ne0\), \(dx/y\) extends holomorphically and without zeros. A branch coordinate such as \(y\), rather than \(x\), verifies regularity there. Jacobians carry a principal polarization; arbitrary complex tori need not be Jacobians.',r'The dual vector space, lattice rank, smoothness condition and polarization qualification are supplied. The note does not formulate a solution of the Schottky problem.', 'E',r'The classical analytic construction is the subject of \citet[Ch.~II, \S\S20--21]{forster1981riemann}; verification here is bibliographic.',[FOR],area='Algebraic geometry',speaker='Gelfand (initial only; attribution uncertain)',verification='publisher metadata checked')
item(384,'P000640','method','Jacobi inversion converts linear motion to moving divisors',r'A straight line on the torus produces motion of \(g\) points on the curve.',r'Fix a base point \(Q_0\). The Abel map \(\operatorname{Sym}^gX\to\operatorname{Jac}(X)\), \(Q_1+\cdots+Q_g\mapsto[Q_1+\cdots+Q_g-gQ_0]\), is generically one-to-one: a degree-\(g\) line bundle with \(h^0=1\) has a unique effective divisor. Thus a path \(Z(t)=Z_0+tU\) avoiding the exceptional/special-divisor locus locally determines an unordered moving divisor. Choosing and smoothly following individual ordered points further requires avoiding collisions. The inversion need not be globally single-valued in ordered points.',r'The generic-locus and collision restrictions make precise the drawing\'s motion statement. No differential equation for the individual points is asserted in the notes.', 'E',r'This is the classical Jacobi inversion problem; compare \citet[Ch.~II, \S21]{forster1981riemann}.',[FOR],area='Algebraic geometry',speaker='Gelfand (initial only; attribution uncertain)',verification='publisher metadata checked')

talk(385,'1976-03-15','V. G. Drinfeld','P000641-P000645','Rank-one sheaves and the tangent direction of the Jacobian flow','talk',r'The dated talk starts on P000642, recapitulates the filtered-module correspondence, and identifies its rank-one geometric data and Jacobian velocity. It ends in the upper portion of P000644, before the separate heading A. Polyakov. Gelfand\'s remark about an operator whose higher powers are differential is retained as an independent item; the later sheaf argument requires smooth function germs, a fixed leading coefficient and an acyclic initial line bundle.')
item(385,'P000642','construction','Rank-one homomorphisms and filtered modules revisited',r'The talk restates the rank-one order condition, scalar-gauge equivalence, exhaustive filtration and the two graded isomorphism conditions.',r'Fix the smooth pointed projective curve and differential complex algebra \(B\). The rank-one Krichever homomorphism conditions and the filtered-module axioms of 1975-383.10 are equivalent, modulo a choice of generator of the free rank-one module \(M_0\). Explicitly, \(M=B[D]\), \(a\) acts by right multiplication with \(\varphi(a)\), and \(\nabla\) is left multiplication by \(D\). The nonzero images must have unit leading coefficient; zero has no such coefficient.',r'The equality sign is restored in the opening definition \(A=H^0(X\setminus\{P\},\mathcal O_X)\), where the notes write membership. All subsequent axioms require the whole ring.', 'A',r'The published comparison is \citet[Proposition 2]{drinfeld1977commutative}.',[DRI],area='Algebraic geometry')
item(385,'P000642','claim','A nondifferential operator whose every higher power is differential',r'Gelfand states that there is an operator whose second, third and all subsequent powers are differential operators, although the first is not.',r'Interpret operator in the ring of formal pseudodifferential operators over \(\mathbb C(x)\). Set \(P=D^2-2/x^2\), \(R=D^3-3x^{-2}D+3x^{-3}\). They commute and satisfy \(R^2=P^3\). Hence \(Q=RP^{-1}\) obeys \(Q^2=P\), \(Q^3=R\); since every integer at least two is a nonnegative combination of two and three, all \(Q^m\), \(m\ge2\), are differential. But \(Q\) is not differential: its order and leading coefficient would force \(Q=D+a\), and comparison of the \(D\)-coefficient in \(Q^2=P\) gives \(a=0\), a contradiction. The same example works with smooth germs near any nonzero point.',r'\oursComputed\ The rational degeneration and algebraic verification supply a precise example; the source does not specify the operator category or display the example. This is a verification of classical formulas, not a new existence result.', 'E',r'\citet[\S3, equations (2)--(3), and \S4]{mulase1990geometric} gives the commuting family and formal fractional-power framework.',[MUL],area='Integrable systems',speaker='I. M. Gelfand (intervention)',publication_match='partial')
item(385,'P000642-P000643','theorem','The gap count recalled in residue-class form',r'The least nongap \(n\), the integers \(\mu_i\), their sum \(g\), and the existence of exactly \(g\) missing pole orders are repeated.',r'For a smooth connected projective complex curve of genus \(g\) and a point \(P\), the pole-order semigroup has \(g\) positive gaps. With \(n\) its least positive element and \(i+\mu_i n\) the least element in residue class \(i\), the count is \(g=\sum_{i=1}^{n-1}\mu_i\), as in 1975-383.3. This is a statement about functions having no poles away from \(P\), not about unrestricted meromorphic functions.',r'The sole-pole condition is made explicit; the equivalence follows by counting each residue class.', 'E',r'This repeats the classical gap theory discussed above; \citet[Ch.~II]{forster1981riemann}.',[FOR],area='Algebraic geometry',verification='publisher metadata checked',literal_correctness='correct')
item(385,'P000643','construction','The relative acyclic line bundle and its simple-pole connection',r'The module data, apart from \(\nabla\), specify a line bundle over \(X\otimes B\) with zero cohomology. The remaining operator maps \(L\) to \(L(P)\), is \(\mathcal O_X\)-linear, and satisfies the \(B\)-Leibniz rule.',r'Let \(X_B=X\times\operatorname{Spec}B\). In rank one, the geometric datum is an invertible \(\mathcal O_{X_B}\)-module \(L\) with \(H^0(X_B,L)=H^1(X_B,L)=0\), a trivialization of its rank-one restriction along \(P\) up to the equivalence implicit in the filtered data, and an \(\mathcal O_X\)-linear map \(\nabla:L\to L(P)\) satisfying \(\nabla(bs)=b\nabla s+\delta(b)s\). Its induced polar map \(L/L(-P)\to L(P)/L\) must be an isomorphism. This last condition is the geometric unit-leading-coefficient condition.',r'The polar isomorphism is stated explicitly. For the later dynamical interpretation, \(B\) specializes to smooth germs; arbitrary differential algebras do not automatically possess a value-at-zero map.', 'A',r'\citet[Proposition 2 and proof of Corollary 2]{drinfeld1977commutative} gives this formulation.',[DRI],area='Algebraic geometry')
item(385,'P000643','claim','The reciprocal polar coefficient of the connection',r'After choosing a local frame \(e\), the notes write \(\nabla e/e=1/(b_0z)+\cdots\), where \(b_0\) is the leading coefficient of the homomorphism.',r'Fix the curve coordinate \(z\), and a local generator \(e\) of \(L\) near \(P\). If \(\nabla e=(b_0^{-1}z^{-1}+O(1))e\), \(b_0\in B^*\), then the principal-part datum is \(\beta=b_0^{-1}[z^{-1}]\). Multiplication by \(z^{-m}\) on the associated graded corresponds to \(b_0^m\nabla^m\), giving leading coefficient \(b_0^m\) for the operator attached to a normalized pole of order \(m\). A regular change of frame contributes only a regular logarithmic-derivative term.',r'The reciprocal factor is retained from the manuscript, not changed to \(b_0\); the associated-graded argument explains it.', 'A',r'The datum \(\beta\) is exactly the generator used in \citet[Corollary 2]{drinfeld1977commutative}.',[DRI],area='Algebraic geometry',literal_correctness='correct')
item(385,'P000643','theorem','Initial value and leading coefficient in the rank-one inverse correspondence',r'The theorem is abbreviated to a point of the Jacobian in general position. The construction then uses a natural map \(B\to\mathbb C\), value at zero, to obtain \(L_0\).',r'For \(B\) the algebra of smooth complex-valued germs at zero, evaluation \(B\to\mathbb C\) pulls the family back to its initial line bundle \(L_0\). Fixing a unit leading-coefficient germ \(b_0\), the gauge classes are parametrized by acyclic \(L_0\in\operatorname{Pic}^{g-1}(X)\). If \(b_0\) is not fixed, it is additional data and the Jacobian point alone is insufficient. For an arbitrary differential algebra \(B\), neither evaluation at zero nor this initial-value classification is automatic.',r'The opening general differential-algebra notation is narrowed to the germ setting when evaluation and uniqueness of the path are invoked.', 'A',r'\citet[Corollary 2]{drinfeld1977commutative} states both pieces of data explicitly.',[DRI],area='Algebraic geometry',literal_correctness='correct with missing hypotheses',problem='GP-1975-14')
item(385,'P000643','definition','The Picard group and the tangent space of the Jacobian',r'The tangent space is identified with \(H^1(X,\mathcal O_X)\), but the notes identify the whole Jacobian with \(H^1(X,\mathcal O_X^*)\).',r'For a smooth compact connected complex curve, \(H^1(X,\mathcal O_X^*)=\operatorname{Pic}(X)\) includes all integer degrees. Its identity component is \(\operatorname{Pic}^0(X)=\operatorname{Jac}(X)\). The analytic exponential sequence gives \(\operatorname{Pic}^0(X)\cong H^1(X,\mathcal O_X)/\operatorname{im}H^1(X,\mathbb Z)\), with the conventional \(2\pi i\) factor according to the chosen exponential. Its tangent space at the identity, and by translation at any point, is \(H^1(X,\mathcal O_X)\). A fixed-degree Picard variety is a torsor for this group.',r'The missing degree-zero qualification is corrected; removing the star is interpreted as linearizing transition functions, not as a literal cohomology operation.', 'E',r'The tangent-space identification is used in \citet[Corollary 2, proof]{drinfeld1977commutative}; the surrounding Picard theory is classical.',[DRI],area='Algebraic geometry',literal_correctness='false as written')
item(385,'P000643-P000644','theorem','The principal-part boundary map gives the Jacobian velocity',r'The class of \(1/z\) under the boundary map from \(\mathcal O_X(P)/\mathcal O_X\) is denoted \(\eta_P\), and \(\ell^{\prime}(x)=\eta_P/b_0(x)\). The final explanation identifies its line with the tangent to the Abel image of the curve.',r'Let \(\delta_P:H^0(X,\mathcal O_X(P)/\mathcal O_X)\to H^1(X,\mathcal O_X)\) be the connecting homomorphism and put \(\eta_P=\delta_P([z^{-1}])\). For the smooth-germ rank-one data above, choose the Cech and divisor sign conventions consistently. The corresponding Picard path satisfies \(\ell^{\prime}(x)=b_0(x)^{-1}\eta_P\), hence locally \(\ell(x)=\ell(0)+\eta_P\int_0^x b_0(s)^{-1}\,ds\) in a lift to the universal cover. For \(g\ge1\), the line spanned by \(\eta_P\) is the tangent image of \(X\to\operatorname{Jac}(X)\), \(Q\mapsto[Q-P]\); a chosen tangent coordinate fixes its scale and convention fixes its sign. For genus zero the Jacobian and this vector vanish.',r'The integrated formula, genus-zero exception and sign convention are supplied. The manuscript\'s one-dimensional tangent image needs the positive-genus qualification.', 'A',r'\citet[Corollary 2, proof]{drinfeld1977commutative} identifies the derivative with the boundary image of the principal part.',[DRI],area='Algebraic geometry',problem='GP-1975-14')
problem('GP-1975-14','Rank-one pointed-curve inverse correspondence',r'For a fixed smooth pointed projective complex curve and local parameter, classify rank-one Krichever homomorphisms from its punctured-curve function ring to ordinary differential operators with smooth germ coefficients, modulo unit scalar gauge, including the unit leading-coefficient germ as data.',[rankone,'1975-385.6','1975-385.8'],r'As of November 2026, the precise local correspondence is established: an acyclic degree-(g-1) initial line bundle and a unit leading coefficient determine the homomorphism. Drinfeld1977, Corollary2, gives the statement and attributes it to Krichever. This is distinct from the later higher-rank inverse problem.',[DRI,KRI])
correction('P000642','definition of the function ring',r'\(A\in H^0(X-P,\mathcal O_X)\)',r'\(A=H^0(X-P,\mathcal O_X)\)','The scan has a membership-shaped symbol; the whole construction uses A as this algebra, not one of its elements.',typ='ambiguity')
correction('P000643','Jacobian as multiplicative sheaf cohomology',r'\(J=H^1(X,\mathcal O_X^*)\)',r'\(\operatorname{Pic}(X)=H^1(X,\mathcal O_X^*)\); \(J=\operatorname{Pic}^0(X)\)','The scan and both transcriptions omit the degree-zero component; the notebook simultaneously speaks of bundles of a fixed degree.')
correction('P000643','Jacobian parameterization and value at zero','a Jacobian point alone; natural B to C for the general differential algebra','fix the unit leading coefficient as well; value at zero applies to the stated algebra of smooth germs','The previous page supplies the leading coefficient, and Corollary2 of Drinfeld1977 retains it as independent data. A general complex differential algebra need not have an augmentation.')

